        throw new NotImplementedException();
    }

    // index 위치에 끼워 넣고 뒤의 원소를 한 칸씩 민다. 가득 찼으면 Add 와 같은 규칙으로 늘린다.
    // 허용 범위는 0 .. Count (Count 면 맨 뒤 삽입). 벗어나면 ArgumentOutOfRangeException.
    public void Insert(int index, T item)
