using System;

// 가변 길이 배열. 내부 저장소는 T[] 하나뿐이다.
public sealed class MyList<T>
{
    private const int DefaultCapacity = 4;

    private T[] _items;
    private int _count;

    public MyList()
    {
        _items = new T[0];
    }

    public MyList(int capacity)
    {
        if (capacity < 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _items = new T[capacity];
    }

    public int Count { get { return _count; } }

    public int Capacity { get { return _items.Length; } }

    public T this[int index]
    {
        get
        {
            // 기준은 배열 길이(Capacity)가 아니라 Count 다.
            if (index < 0 || index >= _count) throw new ArgumentOutOfRangeException(nameof(index));
            return _items[index];
        }
        set
        {
            if (index < 0 || index >= _count) throw new ArgumentOutOfRangeException(nameof(index));
            _items[index] = value;
        }
    }

    public void Add(T item)
    {
        if (_count == _items.Length) Grow();
        _items[_count] = item;
        _count++;
    }

    public void Insert(int index, T item)
    {
        // index == Count 는 맨 뒤 삽입이므로 허용한다.
        if (index < 0 || index > _count) throw new ArgumentOutOfRangeException(nameof(index));
        if (_count == _items.Length) Grow();

        // 뒤에서부터 한 칸씩 민다. 앞에서부터 밀면 값이 덮어써진다.
        for (int i = _count; i > index; i--) _items[i] = _items[i - 1];

        _items[index] = item;
        _count++;
    }

    public void RemoveAt(int index)
    {
        if (index < 0 || index >= _count) throw new ArgumentOutOfRangeException(nameof(index));

        _count--;
        // 앞에서부터 한 칸씩 당긴다.
        for (int i = index; i < _count; i++) _items[i] = _items[i + 1];

        // 비게 된 마지막 칸을 지워, 참조 타입 원소가 배열에 남아 GC 되지 못하는 일을 막는다.
        _items[_count] = default(T);
    }

    private void Grow()
    {
        int newCapacity = _items.Length == 0 ? DefaultCapacity : _items.Length * 2;
        T[] bigger = new T[newCapacity];
        for (int i = 0; i < _count; i++) bigger[i] = _items[i];
        _items = bigger;
    }
}

