using System;

// int -> int 해시 테이블 (분리 연결법). 아이템 id -> 보유 개수 같은 용도.
public sealed class IntHashMap
{
    private sealed class Node
    {
        public int Key;
        public int Value;
        public Node Next;
    }

    private const int InitialBuckets = 8;

    private Node[] _buckets = new Node[InitialBuckets];
    private int _count;

    public int Count { get { return _count; } }

    public int BucketCount { get { return _buckets.Length; } }

    // 음수 키도 0 .. bucketCount-1 로 보낸다.
    // uint 로 바꾼 뒤 나머지를 구하므로 int.MinValue 에서도 안전하다.
    private static int IndexFor(int key, int bucketCount)
    {
        return (int)((uint)key % (uint)bucketCount);
    }

    public void Put(int key, int value)
    {
        int index = IndexFor(key, _buckets.Length);
        for (Node n = _buckets[index]; n != null; n = n.Next)
        {
            if (n.Key == key)
            {
                n.Value = value;    // 이미 있는 키: 값만 바꾼다
                return;
            }
        }

        // 새 키: 체인 맨 앞에 붙인다 (O(1))
        Node node = new Node();
        node.Key = key;
        node.Value = value;
        node.Next = _buckets[index];
        _buckets[index] = node;
        _count++;

        // Count > BucketCount * 3/4 를 정수 연산으로 검사한다.
        if ((long)_count * 4 > (long)_buckets.Length * 3) Resize(_buckets.Length * 2);
    }

    public bool TryGet(int key, out int value)
    {
        int index = IndexFor(key, _buckets.Length);
        for (Node n = _buckets[index]; n != null; n = n.Next)
        {
            if (n.Key == key)
            {
                value = n.Value;
                return true;
            }
        }
        value = 0;
        return false;
    }

    public bool Remove(int key)
    {
        int index = IndexFor(key, _buckets.Length);
        Node prev = null;
        for (Node n = _buckets[index]; n != null; prev = n, n = n.Next)
        {
            if (n.Key != key) continue;

            if (prev == null) _buckets[index] = n.Next;   // 체인의 머리를 지우는 경우
            else prev.Next = n.Next;
            _count--;
            return true;
        }
        return false;
    }

    private void Resize(int newBucketCount)
    {
        Node[] bigger = new Node[newBucketCount];
        for (int i = 0; i < _buckets.Length; i++)
        {
            Node n = _buckets[i];
            while (n != null)
            {
                Node next = n.Next;                            // 옮기기 전에 다음 노드를 잡아 둔다
                int index = IndexFor(n.Key, newBucketCount);   // 새 버킷 수로 다시 계산
                n.Next = bigger[index];
                bigger[index] = n;
                n = next;
            }
        }
        _buckets = bigger;
    }
}

