using System;
using System.Collections.Generic;

// 타일 한 칸을 바꾼 기록. 되돌리려면 OldTile, 다시 실행하려면 NewTile 을 쓴다.
public struct TileEdit
{
    public int X;
    public int Y;
    public int OldTile;
    public int NewTile;

    public TileEdit(int x, int y, int oldTile, int newTile)
    {
        X = x;
        Y = y;
        OldTile = oldTile;
        NewTile = newTile;
    }
}

// 레벨 에디터의 타일 맵과 편집 히스토리. 모든 타일은 0 으로 시작한다.
public sealed class LevelEditorHistory
{
    private readonly int[,] _tiles;
    private readonly Stack<TileEdit> _undo = new Stack<TileEdit>();
    private readonly Stack<TileEdit> _redo = new Stack<TileEdit>();

    public LevelEditorHistory(int width, int height)
    {
        _tiles = new int[width, height];
    }

    public int UndoCount { get { return _undo.Count; } }

    public int RedoCount { get { return _redo.Count; } }

    public int GetTile(int x, int y)
    {
        return _tiles[x, y];
    }

    // 타일을 칠한다. 값이 그대로면 아무 일도 하지 않는다(히스토리도 그대로).
    public void SetTile(int x, int y, int tile)
    {
        int old = _tiles[x, y];
        if (old == tile) return;

        _tiles[x, y] = tile;
        _undo.Push(new TileEdit(x, y, old, tile));
        // 수정 1: 새 편집이 생기면 "되돌렸던 미래"는 더 이상 유효하지 않다.
        _redo.Clear();
    }

    // 가장 최근 편집을 되돌린다. 되돌릴 것이 없으면 false.
    public bool Undo()
    {
        // 수정 2: 빈 스택에서 Pop 하면 InvalidOperationException 이 난다.
        if (_undo.Count == 0) return false;

        TileEdit edit = _undo.Pop();
        _tiles[edit.X, edit.Y] = edit.OldTile;
        _redo.Push(edit);
        return true;
    }

    // 가장 최근에 되돌린 편집을 다시 실행한다. 다시 실행할 것이 없으면 false.
    public bool Redo()
    {
        if (_redo.Count == 0) return false;

        TileEdit edit = _redo.Pop();
        _tiles[edit.X, edit.Y] = edit.NewTile;
        // 수정 3: 다시 실행한 편집은 다시 되돌릴 수 있어야 하므로 undo 스택으로 돌아간다.
        _undo.Push(edit);
        return true;
    }
}

