public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static ScoreTree Build(params int[] keys)
    {
        var t = new ScoreTree();
        foreach (int k in keys) t.Insert(k);
        return t;
    }

    static string Show(System.Collections.Generic.IEnumerable<int> xs)
    {
        string s = string.Join(",", xs);
        return "[" + (s.Length > 80 ? s.Substring(0, 80) + "..." : s) + "]";
    }

    // 트리의 InOrder 결과와 Count 가 expected(오름차순)와 같으면 null.
    static string Check(ScoreTree t, System.Collections.Generic.IEnumerable<int> expected, string ctx)
    {
        var exp = new System.Collections.Generic.List<int>(expected);
        var got = new System.Collections.Generic.List<int> { -777, -777 }; // InOrder 가 Clear 해야 한다
        t.InOrder(got);
        bool same = got.Count == exp.Count;
        for (int i = 0; same && i < exp.Count; i++) same = got[i] == exp[i];
        if (!same) return ctx + ": InOrder 기대 " + Show(exp) + ", 결과 " + Show(got);
        if (t.Count != exp.Count) return ctx + ": Count 기대 " + exp.Count + ", 결과 " + t.Count;
        return null;
    }

    public static void Main()
    {
        Run("insert-contains-duplicate", () =>
        {
            var t = new ScoreTree();
            if (t.Count != 0) return "빈 트리의 Count 가 " + t.Count;
            if (t.Contains(5)) return "빈 트리에서 Contains(5) 가 true";
            string e = Check(t, new int[0], "빈 트리");
            if (e != null) return e;
            int[] keys = { 50, 30, 70, 20, 40 };
            foreach (int k in keys) if (!t.Insert(k)) return "Insert(" + k + ") 가 false (새 점수인데)";
            if (t.Insert(30)) return "이미 있는 30 을 Insert 했는데 true";
            if (t.Insert(50)) return "이미 있는 50(루트)을 Insert 했는데 true";
            foreach (int k in keys) if (!t.Contains(k)) return "Contains(" + k + ") 가 false";
            if (t.Contains(35) || t.Contains(10) || t.Contains(80)) return "넣지 않은 점수에 Contains 가 true";
            return Check(t, new[] { 20, 30, 40, 50, 70 }, "50,30,70,20,40,30,50 삽입 후");
        });

        Run("remove-leaf-and-missing", () =>
        {
            var t = Build(50, 30, 70, 20, 40, 60, 80);
            if (t.Remove(55)) return "없는 55 를 Remove 했는데 true";
            string e = Check(t, new[] { 20, 30, 40, 50, 60, 70, 80 }, "없는 점수 Remove 후");
            if (e != null) return e;
            if (!t.Remove(20)) return "리프 20 Remove 가 false";
            if (t.Contains(20)) return "Remove(20) 뒤에도 Contains(20) 이 true";
            if (t.Remove(20)) return "이미 지운 20 을 다시 Remove 했는데 true";
            if (!t.Remove(80)) return "리프 80 Remove 가 false";
            e = Check(t, new[] { 30, 40, 50, 60, 70 }, "리프 20, 80 제거 후");
            if (e != null) return e;
            var one = Build(7);
            if (!one.Remove(7)) return "노드 하나뿐인 트리에서 Remove(7) 이 false";
            e = Check(one, new int[0], "마지막 노드 제거 후");
            if (e != null) return e;
            if (one.Remove(7)) return "빈 트리에서 Remove 가 true";
            if (!one.Insert(3) || !one.Contains(3)) return "비운 트리에 다시 Insert(3) 실패";
            return Check(one, new[] { 3 }, "비운 뒤 재삽입");
        });

        Run("remove-one-child", () =>
        {
            var t = Build(50, 30, 70, 20, 10, 80, 90);
            if (!t.Remove(20)) return "왼쪽 자식만 있는 20 Remove 가 false";
            string e = Check(t, new[] { 10, 30, 50, 70, 80, 90 }, "20 제거 후");
            if (e != null) return e;
            if (!t.Remove(70)) return "오른쪽 자식만 있는 70 Remove 가 false";
            e = Check(t, new[] { 10, 30, 50, 80, 90 }, "70 제거 후");
            if (e != null) return e;
            if (!t.Contains(10) || !t.Contains(80) || !t.Contains(90)) return "지운 노드의 서브트리가 함께 사라짐";
            var chain = Build(1, 2, 3);
            if (!chain.Remove(1)) return "자식 하나인 루트 1 Remove 가 false";
            e = Check(chain, new[] { 2, 3 }, "1,2,3 에서 루트 1 제거 후");
            if (e != null) return e;
            return chain.Contains(2) && chain.Contains(3) ? null : "루트 제거 뒤 2, 3 을 찾지 못함";
        });

        Run("remove-two-children", () =>
        {
            var t = Build(50, 30, 70, 20, 40, 60, 80, 65);
            if (!t.Remove(50)) return "자식 둘인 루트 50 Remove 가 false";
            string e = Check(t, new[] { 20, 30, 40, 60, 65, 70, 80 }, "루트 50 제거 후");
            if (e != null) return e;
            foreach (int k in new[] { 20, 30, 40, 60, 65, 70, 80 }) if (!t.Contains(k)) return "루트 50 제거 뒤 Contains(" + k + ") 가 false";
            if (t.Contains(50)) return "Remove(50) 뒤에도 Contains(50) 이 true";
            if (!t.Remove(30)) return "자식 둘인 30 Remove 가 false";
            e = Check(t, new[] { 20, 40, 60, 65, 70, 80 }, "30 제거 후");
            if (e != null) return e;
            if (!t.Remove(60) || !t.Remove(70)) return "연속 Remove(60), Remove(70) 실패";
            e = Check(t, new[] { 20, 40, 65, 80 }, "60, 70 제거 후");
            if (e != null) return e;
            if (!t.Insert(50) || !t.Contains(50)) return "지운 50 을 다시 Insert 하지 못함";
            return Check(t, new[] { 20, 40, 50, 65, 80 }, "50 재삽입 후");
        });

        Run("extreme-values", () =>
        {
            var t = Build(0, int.MaxValue, int.MinValue, -1, 1);
            string e = Check(t, new[] { int.MinValue, -1, 0, 1, int.MaxValue }, "int.MinValue / int.MaxValue 삽입 후");
            if (e != null) return e;
            if (!t.Contains(int.MinValue) || !t.Contains(int.MaxValue)) return "int.MinValue 또는 int.MaxValue 를 찾지 못함 (뺄셈 비교 오버플로?)";
            if (t.Insert(int.MinValue) || t.Insert(int.MaxValue)) return "극단값 중복 삽입이 true";
            if (!t.Remove(0) || !t.Remove(int.MaxValue)) return "Remove(0) 또는 Remove(int.MaxValue) 가 false";
            e = Check(t, new[] { int.MinValue, -1, 1 }, "0, int.MaxValue 제거 후");
            if (e != null) return e;
            // 극단값끼리 직접 비교되는 삽입 순서: 뺄셈 비교는 여기서 오버플로한다.
            var u = Build(int.MinValue, 1, int.MaxValue, -1);
            e = Check(u, new[] { int.MinValue, -1, 1, int.MaxValue }, "int.MinValue, 1, int.MaxValue, -1 순서로 삽입 후 (뺄셈 비교 오버플로?)");
            if (e != null) return e;
            if (!u.Contains(1) || !u.Contains(int.MaxValue) || !u.Contains(-1)) return "int.MinValue 가 루트인 트리에서 Contains 가 false (뺄셈 비교 오버플로?)";
            var w = Build(int.MaxValue, -2, int.MinValue);
            e = Check(w, new[] { int.MinValue, -2, int.MaxValue }, "int.MaxValue, -2, int.MinValue 순서로 삽입 후 (뺄셈 비교 오버플로?)");
            if (e != null) return e;
            if (!w.Remove(-2) || w.Remove(-2)) return "int.MaxValue 가 루트인 트리에서 Remove(-2) 결과가 틀림";
            return Check(w, new[] { int.MinValue, int.MaxValue }, "-2 제거 후");
        });

        Run("sorted-input", () =>
        {
            const int n = 3000;
            var t = new ScoreTree();
            for (int i = 1; i <= n; i++) if (!t.Insert(i)) return "오름차순 삽입 중 Insert(" + i + ") 가 false";
            var exp = new System.Collections.Generic.List<int>();
            for (int i = 1; i <= n; i++) exp.Add(i);
            string e = Check(t, exp, "1.." + n + " 오름차순 삽입 후");
            if (e != null) return e;
            for (int i = 2; i <= n; i += 2) if (!t.Remove(i)) return "Remove(" + i + ") 가 false";
            exp.RemoveAll(x => x % 2 == 0);
            e = Check(t, exp, "짝수 제거 후");
            if (e != null) return e;
            return t.Contains(n - 1) && !t.Contains(n) ? null : "한쪽으로 치우친 트리에서 Contains 결과가 틀림";
        });

        Run("random-vs-sortedset", () =>
        {
            var rng = new System.Random(20240);
            for (int round = 0; round < 20; round++)
            {
                int range = round < 10 ? 16 : 300;
                var t = new ScoreTree();
                var reference = new System.Collections.Generic.SortedSet<int>();
                for (int step = 0; step < 1500; step++)
                {
                    int k = rng.Next(-range, range);
                    int op = rng.Next(100);
                    string name = op < 45 ? "Insert" : op < 85 ? "Remove" : "Contains";
                    bool want = op < 45 ? reference.Add(k) : op < 85 ? reference.Remove(k) : reference.Contains(k);
                    bool got = op < 45 ? t.Insert(k) : op < 85 ? t.Remove(k) : t.Contains(k);
                    if (want != got) return step + "번째 연산 " + name + "(" + k + "): 기대 " + want + ", 결과 " + got;
                    if (step % 25 == 0 || range == 16)
                    {
                        string e = Check(t, reference, step + "번째 연산 후");
                        if (e != null) return e;
                    }
                }
            }
            return null;
        });
    }
}

