using System;
using System.Collections.Generic;

public static class TilePath
{
    private static readonly int[] DRow = { -1, 1, 0, 0 };
    private static readonly int[] DCol = { 0, 0, -1, 1 };

    public static int ShortestSteps(bool[,] walkable, int startRow, int startCol,
                                    int goalRow, int goalCol)
    {
        int rows = walkable.GetLength(0), cols = walkable.GetLength(1);
        if (!walkable[startRow, startCol] || !walkable[goalRow, goalCol]) return -1;
        if (startRow == goalRow && startCol == goalCol) return 0;

        // dist 가 방문 표시를 겸한다: -1 이면 아직 발견하지 않은 칸.
        var dist = new int[rows, cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                dist[r, c] = -1;

        var queue = new Queue<int>(); // 칸 번호 = row * cols + col
        dist[startRow, startCol] = 0;
        queue.Enqueue(startRow * cols + startCol);

        while (queue.Count > 0)
        {
            int cell = queue.Dequeue();
            int row = cell / cols, col = cell % cols;
            int next = dist[row, col] + 1;

            for (int d = 0; d < 4; d++)
            {
                int nr = row + DRow[d], nc = col + DCol[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (!walkable[nr, nc] || dist[nr, nc] != -1) continue;

                if (nr == goalRow && nc == goalCol) return next;
                dist[nr, nc] = next;           // 큐에 넣는 시점에 표시한다
                queue.Enqueue(nr * cols + nc);
            }
        }
        return -1;
    }
}

