    {
        var m = new bool[lines.Length, lines[0].Length];
        for (int r = 0; r < lines.Length; r++)
            for (int c = 0; c < lines[r].Length; c++)
                m[r, c] = lines[r][c] == '.';
        return m;
    }

    static string Expect(string ctx, bool[,] m, int sr, int sc, int gr, int gc, int expected)
    {
        int got = TilePath.ShortestSteps(m, sr, sc, gr, gc);
        return got == expected ? null : ctx + ": (" + sr + "," + sc + ") -> (" + gr + "," + gc + ") 기대 " + expected + ", 결과 " + got;
    }

    // 참조 구현: 더 줄어들지 않을 때까지 모든 칸을 반복 완화한다(느리지만 단순).
    static int Reference(bool[,] m, int sr, int sc, int gr, int gc)
    {
        int rows = m.GetLength(0), cols = m.GetLength(1);
        const int Inf = int.MaxValue / 2;
        if (!m[sr, sc] || !m[gr, gc]) return -1;
        var d = new int[rows, cols];
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) d[r, c] = Inf;
        d[sr, sc] = 0;
        bool changed = true;
        while (changed)
        {
            changed = false;
            for (int r = 0; r < rows; r++)
                for (int c = 0; c < cols; c++)
                {
                    if (!m[r, c]) continue;
                    int best = d[r, c];
                    if (r > 0 && m[r - 1, c] && d[r - 1, c] + 1 < best) best = d[r - 1, c] + 1;
                    if (r + 1 < rows && m[r + 1, c] && d[r + 1, c] + 1 < best) best = d[r + 1, c] + 1;
                    if (c > 0 && m[r, c - 1] && d[r, c - 1] + 1 < best) best = d[r, c - 1] + 1;
                    if (c + 1 < cols && m[r, c + 1] && d[r, c + 1] + 1 < best) best = d[r, c + 1] + 1;
                    if (best < d[r, c]) { d[r, c] = best; changed = true; }
                }
        }
        return d[gr, gc] >= Inf ? -1 : d[gr, gc];
    }

    public static void Main()
    {
        Run("start-equals-goal", () =>
        {
            string e = Expect("1x1 맵", Map("."), 0, 0, 0, 0, 0);
            if (e != null) return e;
            e = Expect("막힌 1x1 맵", Map("#"), 0, 0, 0, 0, -1);
            if (e != null) return e;
            var m = Map("...", ".#.", "...");
            e = Expect("3x3 맵, 시작 == 도착", m, 2, 1, 2, 1, 0);
            if (e != null) return e;
            return Expect("3x3 맵, 막힌 칸에서 시작 == 도착", m, 1, 1, 1, 1, -1);
        });

        Run("blocked-endpoints", () =>
        {
            var m = Map("#..", "...", "..#");
            string e = Expect("시작 칸이 막힘", m, 0, 0, 1, 1, -1);
            if (e != null) return e;
            e = Expect("도착 칸이 막힘", m, 1, 1, 2, 2, -1);
            if (e != null) return e;
            return Expect("둘 다 막힘", m, 0, 0, 2, 2, -1);
        });

        Run("detour-path", () =>
        {
            var m = Map(
                ".....",
                ".###.",
                ".#...",
                ".#.#.",
                "...#.");
            string e = Expect("바로 옆 칸", m, 0, 0, 0, 1, 1);
            if (e != null) return e;
            e = Expect("벽을 돌아가는 길", m, 0, 0, 2, 2, 8);
            if (e != null) return e;
            e = Expect("반대 방향", m, 2, 2, 0, 0, 8);
            if (e != null) return e;
            e = Expect("아래쪽 통로", m, 4, 0, 4, 2, 2);
            if (e != null) return e;
            return Expect("맨 아래 오른쪽까지", m, 4, 0, 4, 4, 8);
        });

        Run("unreachable-no-diagonal", () =>
        {
            string e = Expect("대각선으로만 붙은 칸", Map(".#", "#."), 0, 0, 1, 1, -1);
            if (e != null) return e;
            var walled = Map(
                "..#..",
                "..#..",
                "###..",
                ".....");
            e = Expect("벽으로 둘러싸인 구역", walled, 0, 0, 3, 4, -1);
            if (e != null) return e;
            return Expect("같은 맵, 닿을 수 있는 쌍", walled, 3, 0, 0, 4, 7);
        });

        Run("non-square-map", () =>
        {
            string e = Expect("1x7 복도", Map("......."), 0, 0, 0, 6, 6);
            if (e != null) return e;
            e = Expect("1x7 복도, 중간이 막힘", Map("...#..."), 0, 0, 0, 6, -1);
            if (e != null) return e;
            e = Expect("6x1 복도", Map(".", ".", ".", ".", ".", "."), 5, 0, 0, 0, 5);
            if (e != null) return e;
            return Expect("2x6 맵", Map("..#...", "......"), 0, 0, 0, 5, 7);
        });

        Run("map-not-modified", () =>
        {
            var m = Map("....", ".##.", "....");
            var copy = (bool[,])m.Clone();
            string e = Expect("첫 번째 호출", m, 0, 0, 2, 3, 5);
            if (e != null) return e;
            for (int r = 0; r < 3; r++) for (int c = 0; c < 4; c++)
                if (m[r, c] != copy[r, c]) return "호출 뒤 walkable[" + r + "," + c + "] 값이 바뀜 (입력 맵을 수정하면 안 됨)";
            return Expect("같은 맵으로 두 번째 호출", m, 0, 0, 2, 3, 5);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(31337);
            for (int t = 0; t < 600; t++)
            {
                int rows = rng.Next(1, 9), cols = rng.Next(1, 9);
                int blockPct = rng.Next(0, 55);
                var m = new bool[rows, cols];
                for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) m[r, c] = rng.Next(100) >= blockPct;
                int sr = rng.Next(rows), sc = rng.Next(cols), gr = rng.Next(rows), gc = rng.Next(cols);
                int want = Reference(m, sr, sc, gr, gc);
                int got = TilePath.ShortestSteps(m, sr, sc, gr, gc);
                if (got == want) continue;
                var text = new string[rows];
                for (int r = 0; r < rows; r++) { var ch = new char[cols]; for (int c = 0; c < cols; c++) ch[c] = m[r, c] ? '.' : '#'; text[r] = new string(ch); }
                return "맵 " + string.Join("/", text) + " 에서 (" + sr + "," + sc + ") -> (" + gr + "," + gc + ") 기대 " + want + ", 결과 " + got;
            }
            return null;
        });

        Run("large-maps", () =>
        {
            const int n = 401;
            var open = new bool[n, n];
            for (int r = 0; r < n; r++) for (int c = 0; c < n; c++) open[r, c] = true;
            string e = Expect(n + "x" + n + " 빈 맵", open, 0, 0, n - 1, n - 1, 2 * (n - 1));
            if (e != null) return e;
            // 지그재그 복도: 짝수 행은 전부 열려 있고, 홀수 행은 한쪽 끝 칸만 열려 있다.
            var snake = new bool[n, n];
            for (int r = 0; r < n; r++)
            {
                if (r % 2 == 0) { for (int c = 0; c < n; c++) snake[r, c] = true; }
                else snake[r, (r % 4 == 1) ? n - 1 : 0] = true;
            }
            // 짝수 행 201개 x 400칸 이동 + 행 사이 이동 400번
            return Expect(n + "x" + n + " 지그재그 복도", snake, 0, 0, n - 1, n - 1, 201 * 400 + 400);
        });
    }
}

