using System;
using System.Collections.Generic;

public static class Pathfinding
{
    // 도달할 수 없는 노드의 거리로 쓰는 값.
    public const long Unreachable = -1;

    public static long[] ShortestDistances(List<(int to, int weight)>[] adj, int source)
    {
        const long Inf = long.MaxValue;
        int n = adj.Length;
        var dist = new long[n];
        for (int i = 0; i < n; i++) dist[i] = Inf;

        // 원소 = 노드 번호, 우선순위 = 큐에 넣을 당시의 거리. 우선순위가 작은 것부터 나온다.
        var pq = new PriorityQueue<int, long>();
        dist[source] = 0;
        pq.Enqueue(source, 0);

        while (pq.TryDequeue(out int u, out long d))
        {
            // 낡은 항목: 넣은 뒤에 u 까지 더 짧은 길이 발견되어 이미 처리된 경우
            if (d > dist[u]) continue;

            foreach (var (to, weight) in adj[u])
            {
                long candidate = d + weight; // d 는 Inf 가 아니므로 넘치지 않는다
                if (candidate < dist[to])
                {
                    dist[to] = candidate;
                    pq.Enqueue(to, candidate); // decrease-key 대신 새 항목을 넣는다
                }
            }
        }

        for (int i = 0; i < n; i++)
            if (dist[i] == Inf) dist[i] = Unreachable;
        return dist;
    }
}

