        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // edges 는 (from, to, weight) 를 이어 쓴 배열.
    static System.Collections.Generic.List<(int to, int weight)>[] Graph(int n, params int[] edges)
    {
        var adj = new System.Collections.Generic.List<(int to, int weight)>[n];
        for (int i = 0; i < n; i++) adj[i] = new System.Collections.Generic.List<(int to, int weight)>();
        for (int i = 0; i < edges.Length; i += 3) adj[edges[i]].Add((edges[i + 1], edges[i + 2]));
        return adj;
    }

    static string Show(long[] xs)
    {
        if (xs == null) return "null";
        string s = string.Join(",", xs);
        return "[" + (s.Length > 70 ? s.Substring(0, 70) + "..." : s) + "]";
    }

    static string Expect(string ctx, System.Collections.Generic.List<(int to, int weight)>[] adj, int source, params long[] expected)
    {
        long[] got = Pathfinding.ShortestDistances(adj, source);
        if (got == null || got.Length != expected.Length) return ctx + ": 길이 " + expected.Length + " 인 배열을 기대, 결과 " + Show(got);
        for (int i = 0; i < expected.Length; i++)
            if (got[i] != expected[i]) return ctx + ": 출발 " + source + " 에서 노드 " + i + " 까지 기대 " + expected[i] + ", 결과 " + got[i] + " (전체 기대 " + Show(expected) + ")";
        return null;
    }

    // 참조 구현: 벨만-포드(모든 간선을 n-1 번 완화).
    static long[] Reference(System.Collections.Generic.List<(int to, int weight)>[] adj, int source)
    {
        int n = adj.Length;
        var d = new long[n];
        for (int i = 0; i < n; i++) d[i] = long.MaxValue;
        d[source] = 0;
        for (int round = 0; round < n; round++)
            for (int u = 0; u < n; u++)
            {
                if (d[u] == long.MaxValue) continue;
                foreach (var e in adj[u]) if (d[u] + e.weight < d[e.to]) d[e.to] = d[u] + e.weight;
            }
        for (int i = 0; i < n; i++) if (d[i] == long.MaxValue) d[i] = -1;
        return d;
    }

    public static void Main()
    {
        Run("single-node", () =>
        {
            string e = Expect("노드 1개, 간선 없음", Graph(1), 0, 0);
            if (e != null) return e;
            return Expect("노드 1개, 자기 자신으로 가는 간선", Graph(1, 0, 0, 7), 0, 0);
        });

