using System;

public static class LevelTable
{
    // expToReach[i] = 레벨 (i + 2) 에 도달하는 데 필요한 누적 경험치 (오름차순, 같은 값 허용)
    // 반환: 누적 경험치 exp 를 가진 캐릭터의 레벨 = 1 + (expToReach 중 exp 이하인 값의 개수)
    public static int LevelFor(int[] expToReach, int exp)
    {
        // upper bound: expToReach[i] > exp 인 첫 인덱스를 찾는다. 없으면 Length.
        // 불변식: [0, lo) 는 모두 exp 이하, [hi, Length) 는 모두 exp 초과.
        int lo = 0;
        int hi = expToReach.Length;          // 답이 Length 일 수 있으므로 후보 범위는 [0, Length]
        while (lo < hi)
        {
            int mid = lo + (hi - lo) / 2;    // lo <= mid < hi, 덧셈 오버플로 없음
            if (expToReach[mid] <= exp)
                lo = mid + 1;                // mid 는 exp 이하 -> 답은 mid 오른쪽
            else
                hi = mid;                    // mid 는 exp 초과 -> mid 자신이 답일 수 있다
        }
        return lo + 1;                       // exp 이하인 값의 개수(lo) + 시작 레벨 1
    }
}

