        {
            if (!Reported.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Report(id, err);
    }

    // 학습자 코드가 끝나지 않아도 채점이 멈추지 않도록 별도 스레드에서 실행하고 제한 시간을 둔다.
    public static void Main()
    {
        var worker = new System.Threading.Thread(RunAll) { IsBackground = true };
        worker.Start();
        if (worker.Join(2500)) return;
        foreach (string id in Cases) Report(id, "시간 초과(2.5초): 반복이 끝나지 않거나 시간복잡도가 O(n·W) 를 넘습니다");
        System.Console.Out.Flush();
        System.Environment.Exit(0);
    }

    static string Expect(int[] w, int[] v, int cap, int want)
    {
        int got = Inventory.MaxValue(w, v, cap);
        if (got == want) return null;
        string desc = w.Length <= 12 ? "weights=[" + string.Join(",", w) + "], values=[" + string.Join(",", v) + "]" : "아이템 " + w.Length + "개";
        return desc + ", capacity=" + cap + ": 기대 " + want + " / 결과 " + got;
    }

    // 기준 구현 1: 모든 부분집합을 열거한다(n <= 10).
    static int Brute(int[] w, int[] v, int cap)
    {
        int best = 0;
        for (int mask = 0; mask < (1 << w.Length); mask++)
        {
            int sw = 0, sv = 0;
            for (int i = 0; i < w.Length; i++) if ((mask & (1 << i)) != 0) { sw += w[i]; sv += v[i]; }
            if (sw <= cap && sv > best) best = sv;
        }
        return best;
    }

    // 기준 구현 2: 교과서식 2차원 표 t[i][c] = 앞의 i 개로 한도 c 에서의 최댓값.
    static int Table2D(int[] w, int[] v, int cap)
    {
        var t = new int[w.Length + 1][];
        t[0] = new int[cap + 1];
        for (int i = 1; i <= w.Length; i++)
        {
            t[i] = new int[cap + 1];
            for (int c = 0; c <= cap; c++)
            {
                t[i][c] = t[i - 1][c];
                if (c >= w[i - 1] && t[i - 1][c - w[i - 1]] + v[i - 1] > t[i][c]) t[i][c] = t[i - 1][c - w[i - 1]] + v[i - 1];
            }
        }
        return t[w.Length][cap];
    }

    static void RunAll()
    {
        Run("empty-or-zero-capacity", () =>
            Expect(new int[0], new int[0], 10, 0) ?? Expect(new[] { 1, 2 }, new[] { 5, 6 }, 0, 0) ?? Expect(new int[0], new int[0], 0, 0));

        Run("single-item", () =>
            Expect(new[] { 5 }, new[] { 10 }, 5, 10) ?? Expect(new[] { 5 }, new[] { 10 }, 4, 0) ?? Expect(new[] { 5 }, new[] { 10 }, 100, 10));

        Run("each-item-only-once", () =>
            Expect(new[] { 2 }, new[] { 3 }, 6, 3) ?? Expect(new[] { 1, 3 }, new[] { 10, 5 }, 5, 15) ?? Expect(new[] { 1, 1 }, new[] { 4, 4 }, 10, 8));

        Run("greedy-ratio-trap", () =>
            Expect(new[] { 6, 5, 5 }, new[] { 30, 20, 20 }, 10, 40) ?? Expect(new[] { 1, 10 }, new[] { 2, 10 }, 10, 10));

        Run("basic-combinations", () =>
            Expect(new[] { 3, 4, 5 }, new[] { 4, 5, 6 }, 7, 9) ?? Expect(new[] { 1, 3, 4, 5 }, new[] { 1, 4, 5, 7 }, 7, 9)
            ?? Expect(new[] { 2, 3, 4 }, new[] { 0, 0, 0 }, 9, 0) ?? Expect(new[] { 12, 2, 1, 1, 4 }, new[] { 4, 2, 1, 2, 10 }, 15, 15));

        Run("random-vs-bruteforce", () =>
        {
            var rng = new System.Random(8128);
            for (int run = 0; run < 400; run++)
            {
                int n = rng.Next(0, 11);
                var w = new int[n]; var v = new int[n];
                for (int i = 0; i < n; i++) { w[i] = rng.Next(1, 9); v[i] = rng.Next(0, 20); }
                int cap = rng.Next(0, 30);
                string e = Expect(w, v, cap, Brute(w, v, cap));
                if (e != null) return e;
            }
            return null;
        });

        Run("large-200-items", () =>
        {
            // 아이템 200개, 한도 5000: 부분집합 열거나 메모 없는 재귀는 제한 시간을 넘는다.
            var rng = new System.Random(2718);
            const int n = 200;
            var w = new int[n]; var v = new int[n];
            for (int i = 0; i < n; i++) { w[i] = rng.Next(1, 300); v[i] = rng.Next(0, 100001); }
            return Expect(w, v, 5000, Table2D(w, v, 5000)) ?? Expect(w, v, 137, Table2D(w, v, 137));
        });
    }
}

