using System;

// 순찰 경로의 웨이포인트 하나. Next 가 null 이면 경로의 끝.
public sealed class WaypointNode
{
    public int Id;
    public WaypointNode Next;
    public WaypointNode(int id) { Id = id; }
}

public static class PatrolRoute
{
    // index 위치(0 = 맨 앞, 길이 = 맨 뒤)에 Id 가 id 인 새 노드를 끼워 넣고 새 head 를 반환한다.
    // index < 0 이거나 index > 길이 이면 ArgumentOutOfRangeException.
    public static WaypointNode InsertAt(WaypointNode head, int index, int id)
    {
        if (index < 0) throw new ArgumentOutOfRangeException(nameof(index));

        var node = new WaypointNode(id);
        if (index == 0)
        {
            node.Next = head;            // 빈 리스트(head == null)도 이 한 줄로 처리된다
            return node;
        }

        // 삽입 위치의 "바로 앞" 노드(index - 1 번째)까지 걸어간다.
        WaypointNode prev = head;
        for (int i = 0; i < index - 1 && prev != null; i++)
            prev = prev.Next;
        if (prev == null) throw new ArgumentOutOfRangeException(nameof(index));

        node.Next = prev.Next;           // 먼저 새 노드가 뒤쪽을 붙잡고
        prev.Next = node;                // 그다음 앞 노드가 새 노드를 가리킨다
        return head;
    }

    // Id 가 id 인 노드 중 가장 앞의 하나만 떼어 내고 새 head 를 반환한다. 없으면 그대로 둔다.
    public static WaypointNode RemoveFirst(WaypointNode head, int id)
    {
        if (head == null) return null;
        if (head.Id == id) return head.Next;     // head 를 지우면 head 자체가 바뀐다

        // 지울 노드의 "바로 앞" 노드를 찾는다: 단일 연결 리스트는 뒤로 갈 수 없다.
        WaypointNode prev = head;
        while (prev.Next != null && prev.Next.Id != id)
            prev = prev.Next;

        if (prev.Next != null)
            prev.Next = prev.Next.Next;          // 지울 노드를 건너뛰게 연결
        return head;
    }

    // 노드를 새로 만들지 않고 Next 방향만 뒤집은 뒤 새 head 를 반환한다.
    public static WaypointNode Reverse(WaypointNode head)
    {
        WaypointNode prev = null;        // 이미 뒤집힌 부분의 head
        WaypointNode cur = head;         // 아직 안 뒤집힌 부분의 head
        while (cur != null)
        {
            WaypointNode next = cur.Next;    // 끊기 전에 다음 노드를 잡아 둔다
            cur.Next = prev;
            prev = cur;
            cur = next;
        }
        return prev;
    }

    // Next 를 따라가다 이미 지난 노드로 되돌아오는 경로이면 true. 리스트를 수정하지 않는다.
    public static bool HasCycle(WaypointNode head)
    {
        // 플로이드의 토끼와 거북이: slow 는 한 칸, fast 는 두 칸씩 간다.
        WaypointNode slow = head;
        WaypointNode fast = head;
        while (fast != null && fast.Next != null)
        {
            slow = slow.Next;
            fast = fast.Next.Next;
            if (ReferenceEquals(slow, fast)) return true;   // 값(Id)이 아니라 같은 노드인지 비교
        }
        return false;                    // fast 가 끝(null)에 닿았다 = 순환 없음
    }
}

