public static class __Judge
{
    static readonly object Gate = new object();
    static readonly System.Collections.Generic.HashSet<string> Reported = new System.Collections.Generic.HashSet<string>();
    static readonly string[] Cases = { "insert-positions", "insert-out-of-range", "remove-first-match", "reverse-in-place", "cycle-absent", "cycle-present", "random-vs-list", "large-route-iterative" };

    static void Report(string id, string err)
    {
        lock (Gate)
        {
            if (!Reported.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    // 스택 오버플로는 catch 할 수 없이 프로세스를 끝낸다. 그럴 수 있는 케이스는 실패 사유(ifKilled)를 먼저 출력해 두고,
    // 끝까지 실행되면 뒤에 출력되는 줄이 그것을 대신한다(같은 케이스 이름은 마지막 줄이 결과다).
    static void Run(string id, System.Func<string> body, string ifKilled = null)
    {
        if (ifKilled != null) lock (Gate) { System.Console.WriteLine("[FAIL] " + id + " :: " + ifKilled); }
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Report(id, err);
    }

    // 학습자 코드가 끝나지 않아도 채점이 멈추지 않도록 별도 스레드(스택 1MB)에서 실행하고 제한 시간을 둔다.
    public static void Main()
    {
        var worker = new System.Threading.Thread(RunAll, 1 << 20) { IsBackground = true };
        worker.Start();
        if (worker.Join(2500)) return;
        foreach (string id in Cases) Report(id, "시간 초과(2.5초): 순환이 있는 경로에서 반복문이 끝나지 않거나, 연산이 리스트를 순환하게 만들었습니다");
        System.Console.Out.Flush();
        System.Environment.Exit(0);
    }

    static WaypointNode Build(params int[] ids)
    {
        WaypointNode head = null, tail = null;
        foreach (int id in ids)
        {
            var n = new WaypointNode(id);
            if (head == null) head = n; else tail.Next = n;
            tail = n;
        }
        return head;
    }

    // 최대 limit 개까지만 따라간다: 학습자 코드가 순환을 만들어도 채점기가 멈추지 않는다.
    static string Show(WaypointNode head, int limit = 64)
    {
        var sb = new System.Text.StringBuilder("[");
        int k = 0;
        for (var n = head; n != null; n = n.Next)
        {
            if (k == limit) { sb.Append(",...(끝나지 않음)"); break; }
            if (k++ > 0) sb.Append(',');
            sb.Append(n.Id);
        }
        return sb.Append(']').ToString();
    }

    static string Same(string ctx, WaypointNode head, params int[] want)
    {
        string w = "[" + string.Join(",", want) + "]", g = Show(head, want.Length + 8);
        return g == w ? null : ctx + ": 기대 " + w + " / 결과 " + g;
    }

    static string Throws(string ctx, System.Action act)
    {
        try { act(); }
        catch (System.ArgumentOutOfRangeException) { return null; }
        catch (System.Exception e) { return ctx + ": ArgumentOutOfRangeException 을 기대했지만 " + e.GetType().Name; }
        return ctx + ": ArgumentOutOfRangeException 을 기대했지만 예외가 없었습니다";
    }

    static WaypointNode[] Nodes(int n)
    {
        var a = new WaypointNode[n];
        for (int i = 0; i < n; i++) a[i] = new WaypointNode(i + 1);
        for (int i = 0; i + 1 < n; i++) a[i].Next = a[i + 1];
        return a;
    }

    // 길이 n 인 리스트의 꼬리를 target 번 인덱스 노드에 이어 순환을 만든 뒤 HasCycle 을 확인하고, 연결이 그대로인지 본다.
    static string CycleCheck(int n, int target)
    {
        var a = Nodes(n);
        a[n - 1].Next = a[target];
        string ctx = "노드 " + n + "개, 꼬리.Next = " + target + "번 인덱스 노드";
        if (!PatrolRoute.HasCycle(a[0])) return ctx + ": 기대 true / 결과 false";
        for (int i = 0; i < n; i++)
            if (!ReferenceEquals(a[i].Next, i + 1 < n ? a[i + 1] : a[target])) return ctx + ": HasCycle 이 리스트의 연결을 바꿨습니다";
        return null;
    }

    static void RunAll()
    {
        Run("insert-positions", () =>
            Same("빈 리스트에 InsertAt(null, 0, 7)", PatrolRoute.InsertAt(null, 0, 7), 7)
            ?? Same("[1,2,3] 에 InsertAt(0, 9)", PatrolRoute.InsertAt(Build(1, 2, 3), 0, 9), 9, 1, 2, 3)
            ?? Same("[1,2,3] 에 InsertAt(1, 9)", PatrolRoute.InsertAt(Build(1, 2, 3), 1, 9), 1, 9, 2, 3)
            ?? Same("[1,2,3] 에 InsertAt(2, 9)", PatrolRoute.InsertAt(Build(1, 2, 3), 2, 9), 1, 2, 9, 3)
            ?? Same("[1,2,3] 에 InsertAt(3, 9) (맨 뒤)", PatrolRoute.InsertAt(Build(1, 2, 3), 3, 9), 1, 2, 3, 9)
            ?? Same("[5] 에 InsertAt(1, 6)", PatrolRoute.InsertAt(Build(5), 1, 6), 5, 6));

        Run("insert-out-of-range", () =>
            Throws("[1,2,3] 에 InsertAt(-1, 9)", () => PatrolRoute.InsertAt(Build(1, 2, 3), -1, 9))
            ?? Throws("[1,2,3] 에 InsertAt(4, 9)", () => PatrolRoute.InsertAt(Build(1, 2, 3), 4, 9))
            ?? Throws("[1,2,3] 에 InsertAt(100, 9)", () => PatrolRoute.InsertAt(Build(1, 2, 3), 100, 9))
            ?? Throws("빈 리스트에 InsertAt(null, 1, 9)", () => PatrolRoute.InsertAt(null, 1, 9)));

        Run("remove-first-match", () =>
            Same("[1,2,3] 에서 RemoveFirst(1) (head)", PatrolRoute.RemoveFirst(Build(1, 2, 3), 1), 2, 3)
            ?? Same("[1,2,3] 에서 RemoveFirst(2)", PatrolRoute.RemoveFirst(Build(1, 2, 3), 2), 1, 3)
            ?? Same("[1,2,3] 에서 RemoveFirst(3) (꼬리)", PatrolRoute.RemoveFirst(Build(1, 2, 3), 3), 1, 2)
            ?? Same("[1,2,3] 에서 RemoveFirst(9) (없는 값)", PatrolRoute.RemoveFirst(Build(1, 2, 3), 9), 1, 2, 3)
            ?? Same("[5,7,5,7] 에서 RemoveFirst(7) (첫 번째만)", PatrolRoute.RemoveFirst(Build(5, 7, 5, 7), 7), 5, 5, 7)
            ?? Same("[7,7,7] 에서 RemoveFirst(7)", PatrolRoute.RemoveFirst(Build(7, 7, 7), 7), 7, 7)
            ?? Same("[4] 에서 RemoveFirst(4)", PatrolRoute.RemoveFirst(Build(4), 4))
            ?? Same("빈 리스트에서 RemoveFirst(null, 4)", PatrolRoute.RemoveFirst(null, 4)));

        Run("reverse-in-place", () =>
        {
            if (PatrolRoute.Reverse(null) != null) return "Reverse(null): 기대 null";
            var one = new WaypointNode(8);
            var r1 = PatrolRoute.Reverse(one);
            if (!ReferenceEquals(r1, one) || one.Next != null) return "노드 1개: 같은 노드가 그대로 반환되어야 합니다";
            foreach (int n in new[] { 2, 3, 5, 6 })
            {
                var a = Nodes(n);
                var h = PatrolRoute.Reverse(a[0]);
                var want = new int[n];
                for (int i = 0; i < n; i++) want[i] = n - i;
                string e = Same("[1.." + n + "] 을 Reverse", h, want);
                if (e != null) return e;
                var cur = h;
                for (int i = n - 1; i >= 0; i--, cur = cur.Next)
                    if (!ReferenceEquals(cur, a[i])) return "[1.." + n + "] 을 Reverse: 값은 맞지만 원래 노드 객체를 재사용하지 않았습니다(새 노드를 만들면 안 됩니다)";
            }
            return null;
        });

        Run("cycle-absent", () =>
        {
            if (PatrolRoute.HasCycle(null)) return "HasCycle(null): 기대 false / 결과 true";
            foreach (int n in new[] { 1, 2, 3, 4, 7, 1000 })
            {
                var a = Nodes(n);
                if (PatrolRoute.HasCycle(a[0])) return "순환 없는 노드 " + n + "개: 기대 false / 결과 true";
                for (int i = 0; i < n; i++)
                    if (!ReferenceEquals(a[i].Next, i + 1 < n ? a[i + 1] : null)) return "순환 없는 노드 " + n + "개: HasCycle 이 리스트의 연결을 바꿨습니다";
            }
            // Id 가 같은 노드가 여러 개 있어도 순환이 아니다.
            if (PatrolRoute.HasCycle(Build(3, 3, 3, 3, 3))) return "[3,3,3,3,3] (같은 Id, 순환 없음): 기대 false / 결과 true";
            return PatrolRoute.HasCycle(Build(1, 2, 1, 2, 1, 2)) ? "[1,2,1,2,1,2] (순환 없음): 기대 false / 결과 true" : null;
        });

        Run("cycle-present", () =>
            CycleCheck(1, 0) ?? CycleCheck(2, 0) ?? CycleCheck(2, 1) ?? CycleCheck(3, 0) ?? CycleCheck(5, 0)
            ?? CycleCheck(10, 3) ?? CycleCheck(11, 10) ?? CycleCheck(11, 4) ?? CycleCheck(1000, 999) ?? CycleCheck(1001, 500));

        Run("random-vs-list", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 300; round++)
            {
                WaypointNode head = null;
                var model = new System.Collections.Generic.List<int>();
                for (int step = 0; step < 40; step++)
                {
                    int op = rng.Next(10);
                    string what;
                    if (op < 5)
                    {
                        int idx = rng.Next(model.Count + 1), id = rng.Next(6);
                        what = "InsertAt(" + idx + ", " + id + ")";
                        head = PatrolRoute.InsertAt(head, idx, id);
                        model.Insert(idx, id);
                    }
                    else if (op < 8)
                    {
                        int id = rng.Next(6);
                        what = "RemoveFirst(" + id + ")";
                        head = PatrolRoute.RemoveFirst(head, id);
                        model.Remove(id);
                    }
                    else
                    {
                        what = "Reverse()";
                        head = PatrolRoute.Reverse(head);
                        model.Reverse();
                    }
                    string e = Same("무작위 연산 " + (step + 1) + "번째 " + what + " 뒤", head, model.ToArray());
                    if (e != null) return e;
                }
                if (PatrolRoute.HasCycle(head)) return "무작위 연산 뒤 순환 없는 리스트 " + Show(head) + ": HasCycle 기대 false / 결과 true";
            }
            return null;
        });

        Run("large-route-iterative", () =>
        {
            // 노드 50만 개: 재귀로 구현하면 깊이가 길이에 비례해 스택이 넘친다.
            const int n = 500000;
            var a = Nodes(n);
            if (PatrolRoute.HasCycle(a[0])) return "순환 없는 노드 50만 개: HasCycle 기대 false / 결과 true";
            var h = PatrolRoute.Reverse(a[0]);
            if (!ReferenceEquals(h, a[n - 1]) || a[0].Next != null) return "노드 50만 개 Reverse: 새 head 는 원래 꼬리, 원래 head 의 Next 는 null 이어야 합니다";
            int count = 0;
            for (var cur = h; cur != null && count <= n; cur = cur.Next)
            {
                if (cur.Id != n - count) return "노드 50만 개 Reverse: " + count + "번째 Id 기대 " + (n - count) + " / 결과 " + cur.Id;
                count++;
            }
            if (count != n) return "노드 50만 개 Reverse: 길이 기대 " + n + " / 결과 " + count;
            h = PatrolRoute.InsertAt(h, n, 0);
            if (a[0].Next == null || a[0].Next.Id != 0 || a[0].Next.Next != null) return "노드 50만 개의 맨 뒤에 InsertAt(길이, 0): 꼬리 뒤에 새 노드가 붙어야 합니다";
            h = PatrolRoute.RemoveFirst(h, 0);
            if (!ReferenceEquals(h, a[n - 1]) || a[0].Next != null) return "노드 50만 개에서 RemoveFirst(0) (꼬리): 꼬리만 떨어져야 합니다";
            a[0].Next = a[n / 2];
            if (!PatrolRoute.HasCycle(h)) return "노드 50만 개, 꼬리.Next = 가운데 노드: HasCycle 기대 true / 결과 false";
            return null;
        }, "이 케이스를 실행하던 중 프로세스가 종료되었습니다. 노드 50만 개에서 재귀 깊이가 노드 수에 비례하면 스택 오버플로로 이렇게 됩니다(반복문으로 바꾸세요)");
    }
}

