problems.solutionCode:
using System;
using System.Collections.Generic;

public static class DamageFormula
{
    // 중위 표기 수식 expr 을 계산해 반환한다.
    //   피연산자: 음이 아닌 정수 리터럴, 변수 이름(vars 에서 값을 찾는다)
    //   연산자:   + - * / (정수 나눗셈, 0 쪽으로 버림), 단항 -, 괄호
    // 문법 오류는 FormatException, 0 으로 나누면 DivideByZeroException,
    // vars 에 없는 변수는 KeyNotFoundException.
    public static long Evaluate(string expr, Dictionary<string, long> vars)
    {
        if (expr == null) throw new FormatException("수식이 null 입니다.");

        var values = new Stack<long>();   // 아직 쓰이지 않은 피연산자
        var ops = new Stack<char>();      // 아직 적용하지 않은 연산자: + - * / ( 그리고 'u'(단항 -)
        bool expectOperand = true;        // true: 지금 피연산자(또는 '(' / 단항 -)가 올 자리

        int i = 0, n = expr.Length;
        while (i < n)
        {
            char c = expr[i];
            if (c == ' ') { i++; continue; }

            if (c >= '0' && c <= '9')
            {
                if (!expectOperand) throw new FormatException("피연산자가 연달아 나왔습니다: 위치 " + i);
                long v = 0;
                while (i < n && expr[i] >= '0' && expr[i] <= '9')
                {
                    v = v * 10 + (expr[i] - '0');
                    i++;
                }
                values.Push(v);
                expectOperand = false;
            }
            else if (IsNameStart(c))
            {
                if (!expectOperand) throw new FormatException("피연산자가 연달아 나왔습니다: 위치 " + i);
                int start = i;
                while (i < n && (IsNameStart(expr[i]) || (expr[i] >= '0' && expr[i] <= '9'))) i++;
                values.Push(vars[expr.Substring(start, i - start)]);   // 없으면 KeyNotFoundException
                expectOperand = false;
            }
            else if (c == '(')
            {
                if (!expectOperand) throw new FormatException("연산자 없이 '(' 가 나왔습니다: 위치 " + i);
                ops.Push('(');
                i++;
            }
            else if (c == ')')
            {
                if (expectOperand) throw new FormatException("')' 앞에 피연산자가 없습니다: 위치 " + i);
                while (ops.Count > 0 && ops.Peek() != '(') Apply(values, ops.Pop());
                if (ops.Count == 0) throw new FormatException("짝이 없는 ')': 위치 " + i);
                ops.Pop();                // '(' 를 버린다. 괄호 전체가 피연산자 하나가 되었다.
                i++;
            }
            else if (c == '+' || c == '-' || c == '*' || c == '/')
            {
                if (expectOperand)
                {
                    // 피연산자 자리에 나온 '-' 는 단항 연산자. 앞에 적용할 것이 없으므로 그냥 쌓는다.
                    if (c != '-') throw new FormatException("연산자 '" + c + "' 앞에 피연산자가 없습니다: 위치 " + i);
                    ops.Push('u');
                }
                else
                {
                    // 왼쪽 결합: 스택 위의 연산자가 우선순위가 같거나 높으면 먼저 계산한다.
                    while (ops.Count > 0 && ops.Peek() != '(' && Precedence(ops.Peek()) >= Precedence(c))
                        Apply(values, ops.Pop());
                    ops.Push(c);
                    expectOperand = true;
                }
                i++;
            }
            else
            {
                throw new FormatException("알 수 없는 문자 '" + c + "': 위치 " + i);
            }
        }

        if (expectOperand) throw new FormatException("수식이 비어 있거나 연산자로 끝났습니다.");
        while (ops.Count > 0)
        {
            char op = ops.Pop();
            if (op == '(') throw new FormatException("닫히지 않은 '(' 가 있습니다.");
            Apply(values, op);
        }
        return values.Pop();
    }

    private static bool IsNameStart(char c)
    {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_';
    }

    private static int Precedence(char op)
    {
        switch (op)
        {
            case 'u': return 3;           // 단항 -
            case '*':
            case '/': return 2;
            default: return 1;            // + -
        }
    }

    private static void Apply(Stack<long> values, char op)
    {
        if (op == 'u')
        {
            values.Push(-values.Pop());
            return;
        }
        long right = values.Pop();        // 나중에 들어간 쪽이 오른쪽 피연산자
        long left = values.Pop();
        switch (op)
        {
            case '+': values.Push(left + right); break;
            case '-': values.Push(left - right); break;
            case '*': values.Push(left * right); break;
            default: values.Push(left / right); break;   // right == 0 이면 DivideByZeroException
        }
    }
}

