{{USER_CODE}}

public static class __Judge
{
    static readonly object Gate = new object();
    static readonly System.Collections.Generic.HashSet<string> Reported = new System.Collections.Generic.HashSet<string>();
    static readonly string[] Cases = { "precedence-and-parentheses", "unary-minus", "variables", "malformed-format-exception", "divide-by-zero-and-unknown-variable", "random-vs-generator", "long-formula-linear-time", "deep-nesting-explicit-stack" };

    static void Report(string id, string err)
    {
        lock (Gate)
        {
            if (!Reported.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    // 스택 오버플로는 catch 할 수 없이 프로세스를 끝낸다. 그럴 수 있는 케이스는 실패 사유(ifKilled)를 먼저 출력해 두고,
    // 끝까지 실행되면 뒤에 출력되는 줄이 그것을 대신한다(같은 케이스 이름은 마지막 줄이 결과다).
    static void Run(string id, System.Func<string> body, string ifKilled = null)
    {
        if (ifKilled != null) lock (Gate) { System.Console.WriteLine("[FAIL] " + id + " :: " + ifKilled); }
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Report(id, err);
    }

    // 학습자 코드가 끝나지 않아도 채점이 멈추지 않도록 별도 스레드(스택 1MB)에서 실행하고 제한 시간을 둔다.
    public static void Main()
    {
        var worker = new System.Threading.Thread(RunAll, 1 << 20) { IsBackground = true };
        worker.Start();
        if (worker.Join(2500)) return;
        foreach (string id in Cases) Report(id, "시간 초과(2.5초): 반복문이 끝나지 않거나 수식 길이에 대해 O(n) 이 아닙니다");
        System.Console.Out.Flush();
        System.Environment.Exit(0);
    }

    static readonly System.Collections.Generic.Dictionary<string, long> Vars = new System.Collections.Generic.Dictionary<string, long>
    {
        { "atk", 120 }, { "def", 35 }, { "crit_rate", 150 }, { "lv2", 7 }, { "Bonus", -20 }, { "_k", 3 }
    };

    static string Clip(string s) { return s.Length <= 60 ? s : s.Substring(0, 60) + "...(길이 " + s.Length + ")"; }

    static string Eq(string expr, long want)
    {
        long got;
        try { got = DamageFormula.Evaluate(expr, Vars); }
        catch (System.Exception e) { return "\"" + Clip(expr) + "\": 기대 " + want + " / " + e.GetType().Name + " 발생"; }
        return got == want ? null : "\"" + Clip(expr) + "\": 기대 " + want + " / 결과 " + got;
    }

    static string Throws<T>(string expr) where T : System.Exception
    {
        try
        {
            long got = DamageFormula.Evaluate(expr, Vars);
            return "\"" + Clip(expr) + "\": " + typeof(T).Name + " 을 기대했지만 " + got + " 을 반환했습니다";
        }
        catch (T) { return null; }
        catch (System.Exception e) { return "\"" + Clip(expr) + "\": " + typeof(T).Name + " 을 기대했지만 " + e.GetType().Name; }
    }

    // 문법(expr -> term -> factor)을 따라 무작위 수식을 만들면서 값도 함께 계산한다.
    static string Sp(System.Random rng) { return rng.Next(4) == 0 ? " " : ""; }

    static string GenExpr(System.Random rng, int depth, out long value)
    {
        string s = GenTerm(rng, depth, out value);
        int more = rng.Next(3);
        for (int k = 0; k < more; k++)
        {
            long v;
            string t = GenTerm(rng, depth, out v);
            if (rng.Next(2) == 0) { s += Sp(rng) + "+" + Sp(rng) + t; value += v; }
            else { s += Sp(rng) + "-" + Sp(rng) + t; value -= v; }
        }
        return s;
    }

    static string GenTerm(System.Random rng, int depth, out long value)
    {
        string s = GenFactor(rng, depth, out value);
        int more = rng.Next(3);
        for (int k = 0; k < more; k++)
        {
            long v;
            string f = GenFactor(rng, depth, out v);
            if (v != 0 && rng.Next(2) == 0) { s += Sp(rng) + "/" + Sp(rng) + f; value /= v; }
            else { s += Sp(rng) + "*" + Sp(rng) + f; value *= v; }
        }
        return s;
    }

    static string GenFactor(System.Random rng, int depth, out long value)
    {
        int kind = rng.Next(depth > 0 ? 6 : 3);
        if (kind < 3) { value = rng.Next(0, 13); return value.ToString(); }
        if (kind == 3)
        {
            string f = GenFactor(rng, depth - 1, out value);
            value = -value;
            return "-" + Sp(rng) + f;
        }
        string e = GenExpr(rng, depth - 1, out value);
        return "(" + Sp(rng) + e + Sp(rng) + ")";
    }

    static void RunAll()
    {
        Run("precedence-and-parentheses", () =>
            Eq("7", 7) ?? Eq("  12  ", 12) ?? Eq("2+3*4", 14) ?? Eq("2*3+4", 10) ?? Eq("10-4-3", 3) ?? Eq("2-3+4", 3)
            ?? Eq("100/10/5", 2) ?? Eq("100/10*5", 50) ?? Eq("8/3*3", 6) ?? Eq("7/2", 3) ?? Eq("1+2*3-4/2", 5)
            ?? Eq("(2+3)*4", 20) ?? Eq("2*(3+4)*5", 70) ?? Eq("((7))", 7) ?? Eq("10-(4-3)", 9) ?? Eq("100/(10/5)", 50)
            ?? Eq(" ( 1 + 2 ) * ( 3 + 4 ) ", 21) ?? Eq("120 * 35 / 100", 42) ?? Eq("1000000*1000000", 1000000000000L)
            ?? Eq("2*(3+(4-1)*2)-1", 17));

        Run("unary-minus", () =>
            Eq("-3+5", 2) ?? Eq("2*-3", -6) ?? Eq("-(2+3)*2", -10) ?? Eq("2 - -3", 5) ?? Eq("--4", 4) ?? Eq("-7/2", -3)
            ?? Eq("7/-2", -3) ?? Eq("(-2)*(-3)", 6) ?? Eq("-(-(1))", 1) ?? Eq("10--2*3", 16) ?? Eq("- 5", -5) ?? Eq("2-3", -1)
            ?? Eq("4/-(1+1)", -2) ?? Eq("12/-3*2", -8) ?? Eq("2*-3*4+1", -23));

        Run("variables", () =>
            Eq("atk", 120) ?? Eq("(atk*2-def)*crit_rate/100", 307) ?? Eq("atk-def*2", 50) ?? Eq("-atk", -120)
            ?? Eq("lv2*lv2", 49) ?? Eq("atk/def", 3) ?? Eq("atk+Bonus", 100) ?? Eq("_k*(lv2+1)", 24) ?? Eq(" atk * ( 100 + crit_rate ) / 100 - def ", 265));

        Run("malformed-format-exception", () =>
        {
            foreach (string bad in new[] { "", "   ", "2+", "*3", "2 3", "2+*3", "(2+3", "2+3)", "()", "2(3)", "(2)3", "2 $ 3", "+3", "atk def", ")2(", "1.5", "2+()", "(-)", "2 atk", "3-" })
            {
                string e = Throws<System.FormatException>(bad);
                if (e != null) return e;
            }
            return null;
        });

        Run("divide-by-zero-and-unknown-variable", () =>
            Throws<System.DivideByZeroException>("5/0") ?? Throws<System.DivideByZeroException>("5/(3-3)")
            ?? Throws<System.DivideByZeroException>("1+atk/(def-def)") ?? Eq("0/5", 0)
            ?? Throws<System.Collections.Generic.KeyNotFoundException>("atk+mana") ?? Throws<System.Collections.Generic.KeyNotFoundException>("ATK*2"));

        Run("random-vs-generator", () =>
        {
            var rng = new System.Random(7331);
            for (int k = 0; k < 3000; k++)
            {
                long want;
                string expr = GenExpr(rng, 2, out want);
                string e = Eq(expr, want);
                if (e != null) return e;
            }
            return null;
        });

        Run("long-formula-linear-time", () =>
        {
            // 약 90만 글자의 평평한 수식: 문자열을 다시 훑거나 잘라 붙이는 O(n^2) 풀이는 제한 시간을 넘는다.
            var rng = new System.Random(99);
            var sb = new System.Text.StringBuilder();
            long want = 0;
            for (int k = 0; k < 45000; k++)
            {
                long a = rng.Next(1, 1000), b = rng.Next(1, 1000), c = rng.Next(0, 1000), d = rng.Next(1, 50);
                long term = (a * b - c) / d;
                bool minus = k > 0 && rng.Next(2) == 0;
                if (k > 0) sb.Append(minus ? " - " : " + ");
                sb.Append('(').Append(a).Append('*').Append(b).Append(" - ").Append(c).Append(")/").Append(d);
                want += minus ? -term : term;
            }
            return Eq(sb.ToString(), want);
        });

        Run("deep-nesting-explicit-stack", () =>
        {
            // 괄호 10만 겹: 재귀 하강으로 풀면 깊이가 중첩 수에 비례해 스택이 넘친다.
            const int depth = 100000;
            var sb = new System.Text.StringBuilder();
            sb.Append('(', depth).Append('1');
            for (int k = 0; k < depth; k++) sb.Append("+1)");
            string e = Eq(sb.ToString(), depth + 1);
            if (e != null) return e;
            sb.Clear();
            for (int k = 0; k < depth; k++) sb.Append("-(");
            sb.Append('5').Append(')', depth);
            return Eq(sb.ToString(), 5);
        }, "이 케이스를 실행하던 중 프로세스가 종료되었습니다. 괄호 10만 겹에서 재귀 깊이가 중첩 수에 비례하면 스택 오버플로로 이렇게 됩니다(명시적 스택으로 바꾸세요)");
    }
}

