using System;

// 고정 용량 원형 배열 큐. 웨이브 매니저가 스폰할 몬스터 ID 를 넣고, 넣은 순서대로 꺼낸다.
public sealed class SpawnQueue
{
    private readonly int[] _items;
    private int _head;    // 가장 오래된 원소가 있는 칸
    private int _count;   // 들어 있는 원소 수

    public SpawnQueue(int capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _items = new int[capacity];
    }

    public int Count => _count;
    public int Capacity => _items.Length;

    // 맨 뒤에 넣는다. 가득 차 있으면 넣지 않고 false.
    public bool TryEnqueue(int monsterId)
    {
        if (_count == _items.Length - 1) return false;
        _items[_head + _count] = monsterId;
        _count++;
        return true;
    }

    // 가장 오래된 원소를 꺼낸다. 비어 있으면 false.
    public bool TryDequeue(out int monsterId)
    {
        if (_count == 0)
        {
            monsterId = 0;
            return false;
        }
        monsterId = _items[_head];
        _head++;
        _count--;
        return true;
    }

    // 가장 오래된 원소를 꺼내지 않고 본다. 비어 있으면 false.
    public bool TryPeek(out int monsterId)
    {
        if (_count == 0)
        {
            monsterId = 0;
            return false;
        }
        monsterId = _items[_head];
        return true;
    }
}

