public static class __Judge
{
    static readonly object Gate = new object();
    static readonly System.Collections.Generic.HashSet<string> Reported = new System.Collections.Generic.HashSet<string>();
    static readonly string[] Cases = { "fifo-order", "fill-to-capacity", "empty-queue", "peek-keeps-element", "wrap-after-dequeue", "wrap-many-laps", "random-vs-queue" };

    static void Report(string id, string err)
    {
        lock (Gate)
        {
            if (!Reported.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name + (Log.Length > 0 ? " (연산 순서: " + Log + ")" : ""); }
        Report(id, err);
    }

    // 학습자 코드가 끝나지 않아도 채점이 멈추지 않도록 별도 스레드에서 실행하고 제한 시간을 둔다.
    public static void Main()
    {
        var worker = new System.Threading.Thread(RunAll) { IsBackground = true };
        worker.Start();
        if (worker.Join(2500)) return;
        foreach (string id in Cases) Report(id, "시간 초과(2.5초): 반복문이 끝나지 않거나 연산이 O(1) 이 아닙니다");
        System.Console.Out.Flush();
        System.Environment.Exit(0);
    }

    // 지금까지 수행한 연산을 짧게 기록해 실패 사유에 붙인다.
    static readonly System.Text.StringBuilder Log = new System.Text.StringBuilder();
    static SpawnQueue New(int capacity) { Log.Clear(); Log.Append("용량 ").Append(capacity).Append(':'); return new SpawnQueue(capacity); }
    static void Note(string s) { if (Log.Length < 160) Log.Append(' ').Append(s); else if (Log[Log.Length - 1] != '.') Log.Append(" ..."); }

    static string Enq(SpawnQueue q, int v, bool want)
    {
        Note("Enq(" + v + ")");
        bool got = q.TryEnqueue(v);
        return got == want ? null : Log + " → TryEnqueue(" + v + ") 기대 " + want + " / 결과 " + got;
    }

    static string Deq(SpawnQueue q, bool want, int wantValue)
    {
        Note("Deq");
        int v;
        bool got = q.TryDequeue(out v);
        if (got != want) return Log + " → TryDequeue 기대 " + want + " / 결과 " + got;
        return !want || v == wantValue ? null : Log + " → TryDequeue 로 꺼낸 값 기대 " + wantValue + " / 결과 " + v;
    }

    static string Peek(SpawnQueue q, bool want, int wantValue)
    {
        Note("Peek");
        int v;
        bool got = q.TryPeek(out v);
        if (got != want) return Log + " → TryPeek 기대 " + want + " / 결과 " + got;
        return !want || v == wantValue ? null : Log + " → TryPeek 으로 본 값 기대 " + wantValue + " / 결과 " + v;
    }

    static string Cnt(SpawnQueue q, int want)
    {
        return q.Count == want ? null : Log + " → Count 기대 " + want + " / 결과 " + q.Count;
    }

    static void RunAll()
    {
        Run("fifo-order", () =>
        {
            var q = New(8);
            return Enq(q, 10, true) ?? Enq(q, 20, true) ?? Enq(q, 30, true) ?? Cnt(q, 3)
                ?? Deq(q, true, 10) ?? Deq(q, true, 20) ?? Cnt(q, 1) ?? Enq(q, 40, true) ?? Deq(q, true, 30) ?? Deq(q, true, 40) ?? Cnt(q, 0);
        });

        Run("fill-to-capacity", () =>
        {
            var q = New(3);
            string e = Enq(q, 1, true) ?? Enq(q, 2, true) ?? Enq(q, 3, true) ?? Cnt(q, 3) ?? Enq(q, 4, false) ?? Cnt(q, 3)
                ?? Deq(q, true, 1) ?? Deq(q, true, 2) ?? Deq(q, true, 3) ?? Cnt(q, 0);
            if (e != null) return e;
            q = New(1);
            e = Enq(q, 7, true) ?? Cnt(q, 1) ?? Enq(q, 8, false) ?? Deq(q, true, 7);
            if (e != null) return e;
            return q.Capacity == 1 ? null : "Capacity 기대 1 / 결과 " + q.Capacity;
        });

        Run("empty-queue", () =>
        {
            var q = New(2);
            return Deq(q, false, 0) ?? Peek(q, false, 0) ?? Cnt(q, 0) ?? Enq(q, 5, true) ?? Deq(q, true, 5)
                ?? Deq(q, false, 0) ?? Peek(q, false, 0) ?? Cnt(q, 0);
        });

        Run("peek-keeps-element", () =>
        {
            var q = New(4);
            return Enq(q, 11, true) ?? Enq(q, 22, true) ?? Peek(q, true, 11) ?? Peek(q, true, 11) ?? Cnt(q, 2)
                ?? Deq(q, true, 11) ?? Peek(q, true, 22) ?? Cnt(q, 1);
        });

        Run("wrap-after-dequeue", () =>
        {
            // 앞에서 꺼낸 뒤 다시 넣으면 쓰는 위치가 배열 끝을 넘어 0 번 칸으로 돌아와야 한다.
            var q = New(3);
            string e = Enq(q, 1, true) ?? Enq(q, 2, true) ?? Enq(q, 3, true) ?? Deq(q, true, 1) ?? Enq(q, 4, true) ?? Cnt(q, 3)
                ?? Enq(q, 5, false) ?? Deq(q, true, 2) ?? Deq(q, true, 3) ?? Peek(q, true, 4) ?? Deq(q, true, 4) ?? Cnt(q, 0);
            if (e != null) return e;
            q = New(1);
            return Enq(q, 5, true) ?? Deq(q, true, 5) ?? Enq(q, 6, true) ?? Peek(q, true, 6) ?? Deq(q, true, 6) ?? Enq(q, 7, true) ?? Deq(q, true, 7);
        });

        Run("wrap-many-laps", () =>
        {
            // 읽는 위치도 배열 끝에서 0 번 칸으로 돌아와야 한다: 용량 2~5 인 큐를 여러 바퀴 돌린다.
            for (int cap = 2; cap <= 5; cap++)
            {
                var q = New(cap);
                int next = 100, expect = 100;
                for (int lap = 0; lap < 40; lap++)
                {
                    int fill = 1 + lap % cap;
                    for (int k = 0; k < fill; k++) { string e = Enq(q, next++, true); if (e != null) return e; }
                    string c = Cnt(q, fill) ?? Peek(q, true, expect);
                    if (c != null) return c;
                    for (int k = 0; k < fill; k++) { string e = Deq(q, true, expect++); if (e != null) return e; }
                    c = Cnt(q, 0);
                    if (c != null) return c;
                }
            }
            return null;
        });

        Run("random-vs-queue", () =>
        {
            var rng = new System.Random(515);
            for (int round = 0; round < 400; round++)
            {
                int cap = rng.Next(1, 9);
                var q = New(cap);
                var model = new System.Collections.Generic.Queue<int>();
                for (int step = 0; step < 60; step++)
                {
                    int op = rng.Next(10);
                    string e;
                    if (op < 5)
                    {
                        int v = rng.Next(1, 1000);
                        bool ok = model.Count < cap;
                        if (ok) model.Enqueue(v);
                        e = Enq(q, v, ok);
                    }
                    else if (op < 9) e = model.Count > 0 ? Deq(q, true, model.Dequeue()) : Deq(q, false, 0);
                    else e = model.Count > 0 ? Peek(q, true, model.Peek()) : Peek(q, false, 0);
                    e = e ?? Cnt(q, model.Count);
                    if (e != null) return e;
                }
            }
            return null;
        });
    }
}

