using System;

// 연습: 아래 다섯 코드 조각의 시간 복잡도를 "답:" 줄에 적으세요.
// 코드는 고치지 않습니다. 덧셈·비교·배열 칸 하나 읽고 쓰기는 모두 O(1) 로 셉니다.
public static class ComplexityDrill
{
    // [1] 파티원 체력 중 가장 낮은 값.  n = hp.Length
    public static int LowestHp(int[] hp)
    {
        int lowest = int.MaxValue;
        for (int i = 0; i < hp.Length; i++)
            if (hp[i] < lowest) lowest = hp[i];
        return lowest;
    }
    // 답: O(?)   근거(안쪽 문장이 몇 번 실행되는가):

    // [2] 같은 타일에 서 있는 유닛 쌍의 수.  n = tile.Length
    public static int CountSameTilePairs(int[] tile)
    {
        int pairs = 0;
        for (int i = 0; i < tile.Length; i++)
            for (int j = i + 1; j < tile.Length; j++)
                if (tile[i] == tile[j]) pairs++;
        return pairs;
    }
    // 답: O(?)   근거:
    // n = 200 일 때와 n = 2,000 일 때의 비교 횟수, 그리고 몇 배인가:

    // [3] 한 변이 n 칸인 맵을 한 변이 1 칸이 될 때까지 절반으로 줄이는 횟수.  n = size
    public static int HalvingSteps(int size)
    {
        int steps = 0;
        while (size > 1)
        {
            size /= 2;
            steps++;
        }
        return steps;
    }
    // 답: O(?)   근거:

    // [4] 유닛 n 명 각각에 대해 [3] 과 같은 절반 줄이기를 한다.  n = unitCount
    public static long TotalHalvingSteps(int unitCount)
    {
        long total = 0;
        for (int i = 0; i < unitCount; i++)
            for (int span = unitCount; span > 1; span /= 2)
                total++;
        return total;
    }
    // 답: O(?)   근거:

    // [5] 직접 만든 동적 배열. 빈 버퍼에 Add 를 n 번 호출한다.
    public sealed class IntBuffer
