using System;

// 연습: 아래 다섯 코드 조각의 시간 복잡도를 "답:" 줄에 적으세요.
// 코드는 고치지 않습니다. 덧셈·비교·배열 칸 하나 읽고 쓰기는 모두 O(1) 로 셉니다.
public static class ComplexityDrill
{
    // [1] 파티원 체력 중 가장 낮은 값.  n = hp.Length
    public static int LowestHp(int[] hp)
    {
        int lowest = int.MaxValue;
        for (int i = 0; i < hp.Length; i++)
            if (hp[i] < lowest) lowest = hp[i];
        return lowest;
    }
    // 답: O(n)
    // 근거: 루프 본문이 정확히 n 번 실행되고 한 번이 O(1) 이다. 입력 값이 무엇이든 n 번이다.

    // [2] 같은 타일에 서 있는 유닛 쌍의 수.  n = tile.Length
    public static int CountSameTilePairs(int[] tile)
    {
        int pairs = 0;
        for (int i = 0; i < tile.Length; i++)
            for (int j = i + 1; j < tile.Length; j++)
                if (tile[i] == tile[j]) pairs++;
        return pairs;
    }
    // 답: O(n^2)
    // 근거: 비교 횟수 = (n-1) + (n-2) + ... + 1 + 0 = n(n-1)/2 = n^2/2 - n/2.
    //       가장 빨리 자라는 항 n^2 만 남기고 계수 1/2 을 버린다. 안쪽 루프가 i + 1 에서 시작해도 차수는 그대로다.
    // n = 200 이면 200 x 199 / 2 = 19,900 번, n = 2,000 이면 2,000 x 1,999 / 2 = 1,999,000 번: 입력 10배에 약 100배.

    // [3] 한 변이 n 칸인 맵을 한 변이 1 칸이 될 때까지 절반으로 줄이는 횟수.  n = size
    public static int HalvingSteps(int size)
    {
        int steps = 0;
        while (size > 1)
        {
            size /= 2;
            steps++;
        }
        return steps;
    }
    // 답: O(log n)
    // 근거: 한 번 돌 때마다 size 가 절반이 된다. n = 1024 이면 10 번, 100만이면 19 번.
    //       n >= 1 일 때 반복 횟수는 log2(n) 의 내림값이다.

    // [4] 유닛 n 명 각각에 대해 [3] 과 같은 절반 줄이기를 한다.  n = unitCount
    public static long TotalHalvingSteps(int unitCount)
    {
        long total = 0;
        for (int i = 0; i < unitCount; i++)
            for (int span = unitCount; span > 1; span /= 2)
                total++;
        return total;
    }
    // 답: O(n log n)
    // 근거: 바깥 루프 n 번 x 안쪽 루프 (log2(n) 의 내림값) 번. 안쪽 횟수가 i 와 무관하므로 그대로 곱한다.
    //       n = 1024 이면 total = 1024 x 10 = 10240.

    // [5] 직접 만든 동적 배열. 빈 버퍼에 Add 를 n 번 호출한다.
    public sealed class IntBuffer
    {
        private int[] _items = new int[4];
        private int _count;

        public int Count => _count;

        public void Add(int value)
        {
            if (_count == _items.Length)
            {
                var bigger = new int[_items.Length * 2];
                for (int i = 0; i < _count; i++) bigger[i] = _items[i];
                _items = bigger;
            }
            _items[_count] = value;
            _count++;
        }
    }
    // 답: (a) Add 한 번의 최악 O(n)   (b) Add n 번 전체 O(n)   (c) Add 한 번의 분할 상환 O(1)
    // 근거: (a) 배열이 가득 찬 순간의 Add 는 지금까지의 원소를 전부 복사한다.
    //       (b) 복사는 원소 수가 4, 8, 16, ... 일 때만 일어나고, 복사한 원소 수의 합 4 + 8 + 16 + ... 은
    //           마지막 항의 2 배보다 작다. 마지막 항이 n 보다 작으므로 복사 합계 < 2n.
    //           여기에 값을 쓰는 일 n 번을 더해도 3n 미만이다. (새 배열을 만드는 비용도 크기에 비례하므로 같은 식으로 묶인다.)
    //       (c) 전체 O(n) 을 n 번으로 나누면 한 번에 O(1). 가끔 느린 한 번을 나머지 빠른 호출들이 나눠 낸다.
}

