problems.solutionCode:
using System;

// 행동 시각이 가장 이른 유닛부터 꺼내는 이진 힙. compare(a, b) < 0 이면 a 가 b 보다 먼저 나온다.
public sealed class TurnHeap
{
    private int[] _items;                 // 완전 이진 트리를 배열에 담는다: i 의 자식은 2i+1, 2i+2
    private int _count;
    private readonly Comparison<int> _compare;

    // items 의 복사본으로 힙을 만든다(원본 배열은 바꾸지 않는다). O(n).
    public TurnHeap(int[] items, Comparison<int> compare)
    {
        _compare = compare;
        _count = items.Length;
        _items = new int[Math.Max(4, items.Length)];
        Array.Copy(items, _items, items.Length);

        // 플로이드의 방법: 자식이 있는 마지막 노드(n/2 - 1)부터 루트까지 거꾸로 내려 보내기.
        // 리프(n/2 이후)는 그 자체로 이미 힙이므로 건드리지 않는다.
        for (int i = _count / 2 - 1; i >= 0; i--)
            SiftDown(i);
    }

    public int Count => _count;

    // 값을 하나 넣는다. O(log n).
    public void Push(int value)
    {
        if (_count == _items.Length)
            Array.Resize(ref _items, _items.Length * 2);

        // 맨 끝에 놓고, 부모보다 먼저 나와야 하는 동안 위로 올린다.
        int i = _count++;
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (_compare(value, _items[parent]) >= 0) break;
            _items[i] = _items[parent];
            i = parent;
        }
        _items[i] = value;
    }

    // 가장 먼저 나올 값을 꺼내지 않고 본다. 비어 있으면 InvalidOperationException.
    public int Peek()
    {
        if (_count == 0) throw new InvalidOperationException("힙이 비어 있습니다.");
        return _items[0];
    }

    // 가장 먼저 나올 값을 꺼낸다. 비어 있으면 InvalidOperationException. O(log n).
    public int Pop()
    {
        if (_count == 0) throw new InvalidOperationException("힙이 비어 있습니다.");
        int top = _items[0];
        _count--;
        if (_count > 0)
        {
            _items[0] = _items[_count];   // 마지막 원소를 루트로 올리고
            SiftDown(0);                  // 제자리를 찾을 때까지 내려 보낸다
        }
        return top;
    }

    // i 의 값을, 두 자식 중 더 먼저 나와야 하는 쪽과 바꿔 가며 내려 보낸다.
    private void SiftDown(int i)
    {
        int value = _items[i];
        while (true)
        {
            int child = 2 * i + 1;
            if (child >= _count) break;                                   // 자식이 없다
            if (child + 1 < _count && _compare(_items[child + 1], _items[child]) < 0)
                child++;                                                  // 더 먼저 나올 자식
            if (_compare(_items[child], value) >= 0) break;               // 이미 제자리
            _items[i] = _items[child];
            i = child;
        }
        _items[i] = value;
    }
}

public static class TurnSort
{
    // a 를 compare 기준 오름차순(먼저 나와야 하는 값이 앞)으로 제자리 정렬한다. O(n log n), 추가 배열 없음.
    public static void HeapSort(int[] a, Comparison<int> compare)
    {
        int n = a.Length;

        // 1) "가장 나중에 나올 값"이 루트에 오는 최대 힙으로 만든다. O(n).
        for (int i = n / 2 - 1; i >= 0; i--)
            SiftDownMax(a, i, n, compare);

        // 2) 루트(남은 것 중 가장 나중 값)를 힙의 맨 끝과 바꾸고, 힙 크기를 하나 줄인다.
        //    배열 뒤쪽부터 정렬된 구간이 자라난다.
        for (int end = n - 1; end > 0; end--)
        {
            int tmp = a[0]; a[0] = a[end]; a[end] = tmp;
            SiftDownMax(a, 0, end, compare);
        }
    }

    // a[0..n) 을 힙으로 보고, i 의 값을 두 자식 중 더 나중에 나올 쪽과 바꿔 가며 내려 보낸다.
    private static void SiftDownMax(int[] a, int i, int n, Comparison<int> compare)
    {
        int value = a[i];
        while (true)
        {
            int child = 2 * i + 1;
            if (child >= n) break;
            if (child + 1 < n && compare(a[child + 1], a[child]) > 0)
                child++;
            if (compare(a[child], value) <= 0) break;
            a[i] = a[child];
            i = child;
        }
        a[i] = value;
    }
}

