public static class __Judge
{
    static readonly string[] Cases = { "build-pop-order", "source-untouched", "empty-heap-errors", "push-pop-random", "custom-compare", "heapify-linear", "heapsort-fixed", "heapsort-large-inplace" };
    const int CaseLimitMs = 1000, TotalLimitMs = 2600;
    static readonly object Gate = new object();
    static readonly System.Collections.Generic.HashSet<string> Done = new System.Collections.Generic.HashSet<string>();
    static readonly System.Diagnostics.Stopwatch Clock = System.Diagnostics.Stopwatch.StartNew();
    static string Current, CurrentSlow;
    static long CurrentStart;

    static void Emit(string id, string err)
    {
        lock (Gate)
        {
            if (!Done.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    // 같은 케이스 이름은 마지막 줄이 결과다. 프로세스가 죽을 때를 대비해 실패 사유를 먼저 출력해 두고, 끝까지 실행되면 실제 결과가 그 뒤에 출력된다.
    static void Run(string id, System.Func<string> body, string ifSlow = null)
    {
        lock (Gate)
        {
            Current = id; CurrentSlow = ifSlow; CurrentStart = Clock.ElapsedMilliseconds;
            System.Console.WriteLine("[FAIL] " + id + " :: 이 케이스를 실행하던 중 프로세스가 종료되었습니다(끝나지 않는 재귀로 스택이 넘치면 이렇게 됩니다)");
        }
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Emit(id, err);
    }

    // 학습자 코드를 별도 스레드(스택 1MB)에서 실행하고, 케이스 하나가 1초를 넘기면 그 케이스를 시간 초과로 처리한다.
    public static void Main()
    {
        foreach (string id in Cases)
            System.Console.WriteLine("[FAIL] " + id + " :: 앞선 케이스를 실행하던 중 프로세스가 종료되어 이 케이스는 실행되지 못했습니다");
        var worker = new System.Threading.Thread(RunAll, 1 << 20) { IsBackground = true };
        worker.Start();
        while (!worker.Join(20))
        {
            lock (Gate)
            {
                long now = Clock.ElapsedMilliseconds;
                bool running = Current != null && !Done.Contains(Current);
                if (!(running && now - CurrentStart > CaseLimitMs) && now <= TotalLimitMs) continue;
                string stuck = running ? Current : null;
                if (stuck != null) Emit(stuck, CurrentSlow ?? "시간 초과(1초): 반복문이 끝나지 않습니다. 내려 보내기·올리기 반복문의 종료 조건을 확인하세요");
                foreach (string id in Cases)
                    Emit(id, stuck != null ? "앞선 케이스 " + stuck + " 가 제한 시간을 넘겨 이 케이스는 실행되지 못했습니다" : "전체 제한 시간을 넘겨 실행되지 못했습니다");
                System.Console.Out.Flush();
                System.Environment.Exit(0);
            }
        }
    }

    static long Calls;
    static readonly System.Comparison<int> Asc = (x, y) => { Calls++; return x.CompareTo(y); };
    static readonly System.Comparison<int> Desc = (x, y) => { Calls++; return y.CompareTo(x); };

    static string Show(int[] a)
    {
        if (a.Length <= 12) return "[" + string.Join(",", a) + "]";
        var head = new int[12];
        System.Array.Copy(a, head, 12);
        return "[" + string.Join(",", head) + ",... 총 " + a.Length + "개]";
    }

    // items 로 힙을 만들고 전부 꺼내 compare 순서와 같은지 확인한다.
    static string BuildAndDrain(int[] items, System.Comparison<int> compare)
    {
        var src = (int[])items.Clone();
        var want = (int[])items.Clone();
        System.Array.Sort(want, compare);
        var heap = new TurnHeap(src, compare);
        string ctx = "입력 " + Show(items) + " 로 만든 힙";
        if (heap.Count != items.Length) return ctx + ": Count 기대 " + items.Length + " / 결과 " + heap.Count;
        for (int k = 0; k < want.Length; k++)
        {
            int peek = heap.Peek();
            if (peek != want[k]) return ctx + ": " + (k + 1) + "번째 Peek 기대 " + want[k] + " / 결과 " + peek;
            int got = heap.Pop();
            if (got != want[k]) return ctx + ": " + (k + 1) + "번째 Pop 기대 " + want[k] + " / 결과 " + got;
            if (heap.Count != want.Length - k - 1) return ctx + ": Pop " + (k + 1) + "번 뒤 Count 기대 " + (want.Length - k - 1) + " / 결과 " + heap.Count;
        }
        return null;
    }

    static string MustThrow(string ctx, System.Action act)
    {
        try { act(); }
        catch (System.InvalidOperationException) { return null; }
        catch (System.Exception e) { return ctx + ": InvalidOperationException 을 기대했지만 " + e.GetType().Name; }
        return ctx + ": InvalidOperationException 을 기대했지만 예외가 없었습니다";
    }

    static string SortCheck(int[] items, System.Comparison<int> compare, string order)
    {
        var a = (int[])items.Clone();
        var want = (int[])items.Clone();
        System.Array.Sort(want, compare);
        TurnSort.HeapSort(a, compare);
        if (a.Length != want.Length) return "HeapSort(" + Show(items) + ", " + order + "): 길이가 달라졌습니다";
        for (int i = 0; i < a.Length; i++)
            if (a[i] != want[i]) return "HeapSort(" + Show(items) + ", " + order + "): 기대 " + Show(want) + " / 결과 " + Show(a) + (a.Length > 12 ? " (인덱스 " + i + " 에서 기대 " + want[i] + " / 결과 " + a[i] + ")" : "");
        return null;
    }

    static readonly int[][] Fixed =
    {
        new[] { 5, 3, 8, 1, 9, 2 }, new[] { 1, 2, 3, 4, 5 }, new[] { 5, 4, 3, 2, 1 }, new[] { 7 }, new[] { 2, 1 }, new[] { 1, 2 }, new[] { 3, 1, 2 },
        new[] { 2, 2, 1, 1, 3, 3, 2 }, new[] { 4, 4, 4, 4, 4, 4, 4 }, new[] { -5, 0, int.MinValue, int.MaxValue, -1 }, new[] { 9, 1, 8, 2, 7, 3, 6, 4, 5, 0 }
    };

    static void RunAll()
    {
        Run("build-pop-order", () =>
        {
            foreach (var items in Fixed) { string e = BuildAndDrain(items, Asc); if (e != null) return e; }
            return null;
        });

        Run("source-untouched", () =>
        {
            var src = new[] { 6, 2, 9, 4, 1 };
            var heap = new TurnHeap(src, Asc);
            if (string.Join(",", src) != "6,2,9,4,1") return "생성자가 원본 배열을 바꿨습니다: 기대 [6,2,9,4,1] / 결과 " + Show(src);
            heap.Push(0); heap.Push(7);
            int first = heap.Pop();
            if (string.Join(",", src) != "6,2,9,4,1") return "Push/Pop 이 원본 배열을 바꿨습니다(생성자에서 복사해야 합니다): 결과 " + Show(src);
            if (first != 0) return "[6,2,9,4,1] 힙에 0, 7 을 넣은 뒤 Pop: 기대 0 / 결과 " + first;
            for (int i = 0; i < src.Length; i++) src[i] = 100;   // 원본을 바꿔도 힙은 영향을 받지 않아야 한다
            var rest = new int[6];
            for (int i = 0; i < 6; i++) rest[i] = heap.Pop();
            return string.Join(",", rest) == "1,2,4,6,7,9" ? null : "힙을 만든 뒤 원본 배열을 100 으로 덮어썼을 때 남은 Pop 순서: 기대 [1,2,4,6,7,9] / 결과 " + Show(rest);
        });

        Run("empty-heap-errors", () =>
        {
            var heap = new TurnHeap(new int[0], Asc);
            if (heap.Count != 0) return "빈 배열로 만든 힙: Count 기대 0 / 결과 " + heap.Count;
            string e = MustThrow("빈 힙에서 Pop", () => heap.Pop()) ?? MustThrow("빈 힙에서 Peek", () => heap.Peek());
            if (e != null) return e;
            heap.Push(3); heap.Push(1);
            if (heap.Count != 2 || heap.Peek() != 1) return "빈 힙에 3, 1 을 Push: Count 2, Peek 1 을 기대 / 결과 Count " + heap.Count + ", Peek " + heap.Peek();
            int a = heap.Pop(), b = heap.Pop();
            if (a != 1 || b != 3) return "빈 힙에 3, 1 을 Push 한 뒤 Pop 두 번: 기대 1, 3 / 결과 " + a + ", " + b;
            e = MustThrow("전부 꺼낸 힙에서 Pop", () => heap.Pop()) ?? MustThrow("전부 꺼낸 힙에서 Peek", () => heap.Peek());
            if (e != null) return e;
            heap.Push(5);
            return heap.Pop() == 5 && heap.Count == 0 ? null : "비운 힙에 다시 Push(5) 한 뒤 Pop: 기대 5";
        });

        Run("push-pop-random", () =>
        {
            // 빈 힙에서 시작해 내부 배열이 여러 번 커지도록 내림차순으로 넣는다.
            var grow = new TurnHeap(new int[0], Asc);
            for (int v = 1000; v >= 1; v--) grow.Push(v);
            if (grow.Count != 1000) return "빈 힙에 1000 개 Push: Count 기대 1000 / 결과 " + grow.Count;
            for (int v = 1; v <= 1000; v++) { int g = grow.Pop(); if (g != v) return "빈 힙에 1000..1 을 Push 한 뒤 " + v + "번째 Pop: 기대 " + v + " / 결과 " + g; }

            var rng = new System.Random(20261122);
            for (int round = 0; round < 200; round++)
            {
                var init = new int[rng.Next(9)];
                for (int i = 0; i < init.Length; i++) init[i] = rng.Next(40);
                var heap = new TurnHeap(init, Asc);
                var model = new System.Collections.Generic.List<int>(init);
                model.Sort();
                for (int step = 0; step < 120; step++)
                {
                    if (model.Count == 0 || rng.Next(10) < 6)
                    {
                        int v = rng.Next(40);
                        heap.Push(v);
                        int at = model.BinarySearch(v);
                        model.Insert(at < 0 ? ~at : at, v);
                    }
                    else
                    {
                        int want = model[0], got = heap.Pop();
                        model.RemoveAt(0);
                        if (got != want) return "무작위 Push/Pop " + (step + 1) + "번째 연산(Pop): 기대 " + want + " / 결과 " + got + " (시작 배열 " + Show(init) + ")";
                    }
                    if (heap.Count != model.Count) return "무작위 Push/Pop " + (step + 1) + "번째 연산 뒤 Count: 기대 " + model.Count + " / 결과 " + heap.Count;
                    if (model.Count > 0 && heap.Peek() != model[0]) return "무작위 Push/Pop " + (step + 1) + "번째 연산 뒤 Peek: 기대 " + model[0] + " / 결과 " + heap.Peek();
                }
            }
            return null;
        });

        Run("custom-compare", () =>
        {
            // compare 를 뒤집으면 큰 값이 먼저 나와야 한다: int 를 < 로 직접 비교하면 여기서 틀린다.
            foreach (var items in Fixed) { string e = BuildAndDrain(items, Desc); if (e != null) return "(큰 값 먼저 compare) " + e; }
            var heap = new TurnHeap(new[] { 3, 9, 1 }, Desc);
            heap.Push(7); heap.Push(10); heap.Push(0);
            var got = new int[6];
            for (int i = 0; i < 6; i++) got[i] = heap.Pop();
            return string.Join(",", got) == "10,9,7,3,1,0" ? null : "(큰 값 먼저 compare) [3,9,1] 힙에 7, 10, 0 을 Push 한 뒤 Pop 순서: 기대 [10,9,7,3,1,0] / 결과 " + Show(got);
        });

        Run("heapify-linear", () =>
        {
            const int n = 100000;
            for (int pass = 0; pass < 2; pass++)
            {
                // 원소를 하나씩 Push 하는 방식에는 최악인 입력: 뒤에 오는 값일수록 먼저 나와야 한다.
                var items = new int[n];
                for (int i = 0; i < n; i++) items[i] = pass == 0 ? n - i : i + 1;
                var compare = pass == 0 ? Asc : Desc;
                string ctx = pass == 0 ? "내림차순 10만 개(작은 값 먼저)" : "오름차순 10만 개(큰 값 먼저)";
                Calls = 0;
                var heap = new TurnHeap(items, compare);
                long used = Calls;
                if (used > 4L * n) return ctx + ": 생성자가 compare 를 " + used + "번 호출했습니다(기대 4n = " + (4L * n) + "번 이하). 원소를 하나씩 Push 하거나 정렬해서 만들면 O(n log n) 입니다";
                for (int k = 0; k < n; k++)
                {
                    int want = pass == 0 ? k + 1 : n - k, got = heap.Pop();
                    if (got != want) return ctx + ": " + (k + 1) + "번째 Pop 기대 " + want + " / 결과 " + got;
                }
            }
            return null;
        }, "시간 초과(1초): 10만 개로 힙을 만들고 전부 꺼내는 데 1초를 넘겼습니다. Push·Pop 이 O(log n) 인지 확인하세요");

        Run("heapsort-fixed", () =>
        {
            string e = SortCheck(new int[0], Asc, "작은 값 먼저");
            if (e != null) return e;
            foreach (var items in Fixed)
            {
                e = SortCheck(items, Asc, "작은 값 먼저") ?? SortCheck(items, Desc, "큰 값 먼저");
                if (e != null) return e;
            }
            var rng = new System.Random(77);
            for (int round = 0; round < 600; round++)
            {
                var items = new int[rng.Next(40)];
                int range = rng.Next(2) == 0 ? 5 : 1000;
                for (int i = 0; i < items.Length; i++) items[i] = rng.Next(-range, range);
                e = SortCheck(items, Asc, "작은 값 먼저") ?? SortCheck(items, Desc, "큰 값 먼저");
                if (e != null) return e;
            }
            return null;
        });

        Run("heapsort-large-inplace", () =>
        {
            const int n = 100000;
            var rng = new System.Random(4242);
            var items = new int[n];
            for (int i = 0; i < n; i++) items[i] = rng.Next();
            var want = (int[])items.Clone();
            System.Array.Sort(want);
            TurnSort.HeapSort(new[] { 3, 1, 2 }, Asc);   // 측정 전에 한 번 호출해 둔다
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            TurnSort.HeapSort(items, Asc);
            long allocated = System.GC.GetAllocatedBytesForCurrentThread() - before;
            for (int i = 0; i < n; i++)
                if (items[i] != want[i]) return "무작위 10만 개 HeapSort: 인덱스 " + i + " 에서 기대 " + want[i] + " / 결과 " + items[i];
            if (allocated > 65536) return "무작위 10만 개 HeapSort: 정렬 중 약 " + allocated + "바이트를 새로 할당했습니다(기대 64KB 이하). 새 배열이나 힙 객체를 만들지 않고 넘겨받은 배열 안에서 정렬해야 합니다";
            return null;
        }, "시간 초과(1초): 10만 개 HeapSort 가 1초를 넘겼습니다. O(n log n) 인지 확인하세요");
    }
}

