using System;

public static class RankSorter
{
    // scores 를 오름차순으로 제자리 정렬한다.
    public static void Sort(int[] scores)
    {
        Sort(scores, 0, scores.Length - 1);
    }

    private static void Sort(int[] a, int lo, int hi)
    {
        // 큰 쪽 구간은 재귀 대신 이 반복문이 이어서 처리한다.
        while (lo < hi)
        {
            int pivot = MedianOfThree(a[lo], a[lo + (hi - lo) / 2], a[hi]);

            // 호어 분할: i 는 왼쪽에서 pivot 이상인 값을, j 는 오른쪽에서 pivot 이하인 값을 찾아 서로 바꾼다.
            // 반복문 내내 a[lo..i-1] <= pivot, a[j+1..hi] >= pivot 이 성립한다.
            int i = lo - 1, j = hi + 1;
            while (true)
            {
                do { i++; } while (a[i] < pivot);   // pivot 과 같은 값에서도 멈춘다
                do { j--; } while (a[j] > pivot);
                if (i >= j) break;
                Swap(a, i, j);
            }

            // 이제 a[lo..j] <= pivot <= a[j+1..hi] 이고 lo <= j < hi 이므로 두 구간 모두 원래보다 작다.
            // 작은 쪽만 재귀로 내려가면 재귀 깊이는 log2(n) 을 넘지 않는다.
            if (j - lo < hi - j)
            {
                Sort(a, lo, j);
                lo = j + 1;
            }
            else
            {
                Sort(a, j + 1, hi);
                hi = j;
            }
        }
    }

    // 세 값 중 가운데 값.
    private static int MedianOfThree(int x, int y, int z)
    {
        if (x < y)
        {
            if (y < z) return y;          // x < y < z
            return x < z ? z : x;         // y 가 가장 크다
        }
        if (x < z) return x;              // y <= x < z
        return y < z ? z : y;             // x 가 가장 크다
    }

    private static void Swap(int[] a, int i, int j)
    {
        int tmp = a[i]; a[i] = a[j]; a[j] = tmp;
    }
}

