using System;

public static class ProgressionMath
{
    // 1타 기술과 2타 기술만 이어서 정확히 hits 타를 채우는 순서의 수. hits == 0 이면 1(아무것도 쓰지 않는 한 가지).
    public static long CountComboPatterns(int hits)
    {
        if (hits == 0) return 1;
        return CountComboPatterns(hits - 1) + CountComboPatterns(hits - 2);
    }

    // skill 에서 선행 스킬(parent)을 따라 루트까지 올라가는 단계 수. 루트(parent[skill] == -1)는 0.
    public static int PrerequisiteDepth(int[] parent, int skill)
    {
        if (parent[skill] == -1) return 0;
        return 1 + PrerequisiteDepth(parent, parent[skill]);
    }
}

problems.solutionCode:
using System;

public static class ProgressionMath
{
    // 1타 기술과 2타 기술만 이어서 정확히 hits 타를 채우는 순서의 수. hits == 0 이면 1(아무것도 쓰지 않는 한 가지).
    public static long CountComboPatterns(int hits)
    {
        // memo[h] == 0 이면 아직 계산하지 않은 칸이다(실제 답은 항상 1 이상).
        var memo = new long[hits + 1];
        return Count(hits, memo);
    }

    private static long Count(int hits, long[] memo)
    {
        // 기저 조건은 두 개: hits - 2 로 내려가므로 0 과 1 을 모두 막아야 음수로 넘어가지 않는다.
        if (hits <= 1) return 1;
        if (memo[hits] != 0) return memo[hits];      // 이미 푼 문제는 다시 풀지 않는다

        long result = Count(hits - 1, memo) + Count(hits - 2, memo);
        memo[hits] = result;
        return result;
    }

    // skill 에서 선행 스킬(parent)을 따라 루트까지 올라가는 단계 수. 루트(parent[skill] == -1)는 0.
    public static int PrerequisiteDepth(int[] parent, int skill)
    {
        // 한 줄로 이어진 체인은 가지가 없으므로 재귀가 필요 없다: 반복문은 스택을 쓰지 않는다.
        int depth = 0;
        for (int cur = skill; parent[cur] != -1; cur = parent[cur])
            depth++;
        return depth;
    }
}

