problems.solutionCode:
using System;

// 길드 연합 관리: 길드는 0 .. guildCount-1 번호를 갖고, 처음에는 길드마다 혼자인 연합이다.
public sealed class GuildAlliance
{
    private readonly int[] _parent;   // _parent[x] == x 이면 x 가 연합의 대표(루트)
    private readonly int[] _size;     // 루트 칸에만 의미가 있다: 그 연합의 길드 수
    private int _groupCount;

    public GuildAlliance(int guildCount)
    {
        _parent = new int[guildCount];
        _size = new int[guildCount];
        for (int i = 0; i < guildCount; i++)
        {
            _parent[i] = i;
            _size[i] = 1;
        }
        _groupCount = guildCount;
    }

    // 서로 다른 연합의 수.
    public int GroupCount => _groupCount;

    // guild 가 속한 연합의 대표 길드 번호. 같은 연합이면 같은 값을 반환한다.
    public int Find(int guild)
    {
        // 1) 루트까지 올라간다.
        int root = guild;
        while (_parent[root] != root)
            root = _parent[root];

        // 2) 경로 압축: 지나온 노드를 전부 루트에 직접 붙인다.
        while (_parent[guild] != root)
        {
            int next = _parent[guild];
            _parent[guild] = root;
            guild = next;
        }
        return root;
    }

    // a 의 연합과 b 의 연합을 합친다. 이미 같은 연합이면 아무것도 바꾸지 않고 false.
    public bool Union(int a, int b)
    {
        int rootA = Find(a), rootB = Find(b);
        if (rootA == rootB) return false;

        // 크기 기준 합치기: 작은 연합의 루트를 큰 연합의 루트 밑에 붙인다.
        if (_size[rootA] < _size[rootB])
        {
            int tmp = rootA; rootA = rootB; rootB = tmp;
        }
        _parent[rootB] = rootA;
        _size[rootA] += _size[rootB];
        _groupCount--;
        return true;
    }

    // a 와 b 가 같은 연합인가.
    public bool Connected(int a, int b)
    {
        return Find(a) == Find(b);
    }

    // guild 가 속한 연합의 길드 수.
    public int SizeOf(int guild)
    {
        return _size[Find(guild)];
    }
}

