{{USER_CODE}}

public static class __Judge
{
    static readonly string[] Cases = { "initial-singletons", "union-return-values", "transitive-links", "sizes-and-group-count", "random-vs-labels", "long-chain-ascending", "long-chain-descending" };
    const int CaseLimitMs = 1000, TotalLimitMs = 2600;
    static readonly object Gate = new object();
    static readonly System.Collections.Generic.HashSet<string> Done = new System.Collections.Generic.HashSet<string>();
    static readonly System.Diagnostics.Stopwatch Clock = System.Diagnostics.Stopwatch.StartNew();
    static string Current, CurrentSlow;
    static long CurrentStart;

    static void Emit(string id, string err)
    {
        lock (Gate)
        {
            if (!Done.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    // 같은 케이스 이름은 마지막 줄이 결과다. 스택 오버플로는 catch 할 수 없이 프로세스를 끝내므로,
    // 실패 사유(ifKilled)를 먼저 출력해 두고 끝까지 실행되면 실제 결과가 그 뒤에 출력된다.
    static void Run(string id, System.Func<string> body, string ifKilled = null, string ifSlow = null)
    {
        lock (Gate)
        {
            Current = id; CurrentSlow = ifSlow; CurrentStart = Clock.ElapsedMilliseconds;
            System.Console.WriteLine("[FAIL] " + id + " :: " + (ifKilled ?? "이 케이스를 실행하던 중 프로세스가 종료되었습니다(끝나지 않는 재귀로 스택이 넘치면 이렇게 됩니다)"));
        }
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Emit(id, err);
    }

    // 학습자 코드를 별도 스레드(스택 1MB)에서 실행하고, 케이스 하나가 1초를 넘기면 그 케이스를 시간 초과로 처리한다.
    public static void Main()
    {
        foreach (string id in Cases)
            System.Console.WriteLine("[FAIL] " + id + " :: 앞선 케이스를 실행하던 중 프로세스가 종료되어 이 케이스는 실행되지 못했습니다");
        var worker = new System.Threading.Thread(RunAll, 1 << 20) { IsBackground = true };
        worker.Start();
        while (!worker.Join(20))
        {
            lock (Gate)
            {
                long now = Clock.ElapsedMilliseconds;
                bool running = Current != null && !Done.Contains(Current);
                if (!(running && now - CurrentStart > CaseLimitMs) && now <= TotalLimitMs) continue;
                string stuck = running ? Current : null;
                if (stuck != null) Emit(stuck, CurrentSlow ?? "시간 초과(1초): 반복문이 끝나지 않습니다. 부모를 따라 올라가는 반복문이 루트에서 멈추는지 확인하세요");
                foreach (string id in Cases)
                    Emit(id, stuck != null ? "앞선 케이스 " + stuck + " 가 제한 시간을 넘겨 이 케이스는 실행되지 못했습니다" : "전체 제한 시간을 넘겨 실행되지 못했습니다");
                System.Console.Out.Flush();
                System.Environment.Exit(0);
            }
        }
    }

    // 한 연산 뒤의 상태 전체를 정답 라벨(label[x] 가 같으면 같은 연합)과 비교한다.
    static string Compare(string ctx, GuildAlliance g, int[] label)
    {
        int n = label.Length;
        var count = new int[n];
        int groups = 0;
        for (int i = 0; i < n; i++) if (count[label[i]]++ == 0) groups++;
        if (g.GroupCount != groups) return ctx + ": GroupCount 기대 " + groups + " / 결과 " + g.GroupCount;
        var rep = new int[n];
        for (int i = 0; i < n; i++)
        {
            rep[i] = g.Find(i);
            if (rep[i] < 0 || rep[i] >= n) return ctx + ": Find(" + i + ") 가 길드 번호 범위를 벗어난 " + rep[i] + " 을 반환했습니다";
            int size = g.SizeOf(i);
            if (size != count[label[i]]) return ctx + ": SizeOf(" + i + ") 기대 " + count[label[i]] + " / 결과 " + size;
        }
        for (int i = 0; i < n; i++)
        {
            if (label[rep[i]] != label[i]) return ctx + ": Find(" + i + ") = " + rep[i] + " 인데 " + rep[i] + " 는 " + i + " 와 다른 연합입니다";
            if (g.Find(rep[i]) != rep[i]) return ctx + ": Find(" + i + ") = " + rep[i] + " 인데 Find(" + rep[i] + ") = " + g.Find(rep[i]) + " 입니다(대표의 대표는 자기 자신이어야 합니다)";
            for (int j = 0; j < n; j++)
            {
                bool want = label[i] == label[j];
                if ((rep[i] == rep[j]) != want) return ctx + ": Find(" + i + ") 와 Find(" + j + ") 가 " + (want ? "같아야" : "달라야") + " 합니다 / 결과 " + rep[i] + ", " + rep[j];
                if (g.Connected(i, j) != want) return ctx + ": Connected(" + i + ", " + j + ") 기대 " + (want ? "true" : "false") + " / 결과 " + (want ? "false" : "true");
            }
        }
        return null;
    }

    // ops 의 (a, b) 쌍을 차례로 Union 하면서, 매번 반환값과 상태 전체를 확인한다.
    static string Script(int n, params int[] ops)
    {
        var g = new GuildAlliance(n);
        var label = new int[n];
        for (int i = 0; i < n; i++) label[i] = i;
        string history = "길드 " + n + "개";
        string e = Compare(history + ", 처음 상태", g, label);
        if (e != null) return e;
        for (int k = 0; k + 1 < ops.Length; k += 2)
        {
            int a = ops[k], b = ops[k + 1];
            bool want = label[a] != label[b];
            bool got = g.Union(a, b);
            history += ", Union(" + a + "," + b + ")";
            if (got != want) return history + ": 마지막 Union 의 반환값 기대 " + (want ? "true" : "false") + " / 결과 " + (got ? "true" : "false");
            if (want) { int from = label[b], to = label[a]; for (int i = 0; i < n; i++) if (label[i] == from) label[i] = to; }
            e = Compare(history + " 뒤", g, label);
            if (e != null) return e;
        }
        return null;
    }

    // 길드 n 개를 한 줄로 이어 붙인 뒤(오름차순 또는 내림차순 인자 순서) 질의를 많이 던진다.
    static string Chain(bool ascending)
    {
        const int n = 200000;
        string ctx = ascending ? "길드 20만 개, Union(0,1), Union(1,2), ... 순서로 합친 뒤" : "길드 20만 개, Union(1,0), Union(2,1), ... 순서로 합친 뒤";
        var g = new GuildAlliance(n);
        for (int i = 0; i + 1 < n; i++)
        {
            bool merged = ascending ? g.Union(i, i + 1) : g.Union(i + 1, i);
            if (!merged) return ctx.Replace("순서로 합친 뒤", "순서로 합치는 중") + ": " + (i + 1) + "번째 Union 이 false 를 반환했습니다(기대 true)";
        }
        if (g.GroupCount != 1) return ctx + ": GroupCount 기대 1 / 결과 " + g.GroupCount;
        for (int q = 0; q < n; q++)
        {
            int a = q, b = n - 1 - q;
            if (!g.Connected(a, b)) return ctx + ": Connected(" + a + ", " + b + ") 기대 true / 결과 false";
            if (!g.Connected(0, n - 1)) return ctx + ": Connected(0, " + (n - 1) + ") 기대 true / 결과 false";
            if (q % 1000 == 0 && g.SizeOf(a) != n) return ctx + ": SizeOf(" + a + ") 기대 " + n + " / 결과 " + g.SizeOf(a);
        }
        if (g.Union(0, n - 1)) return ctx + ": 이미 같은 연합인 Union(0, " + (n - 1) + ") 기대 false / 결과 true";
        return null;
    }

    const string Killed = "이 케이스를 실행하던 중 프로세스가 종료되었습니다. 트리가 한 줄로 길어진 상태에서 Find 가 재귀로 올라가면 깊이가 길드 수에 비례해 스택 오버플로가 납니다(크기 기준으로 합쳐 트리를 낮게 유지하세요)";
    const string Slow = "시간 초과(1초): 길드 20만 개에서 질의 40만 번이 1초를 넘겼습니다. 트리가 한 줄로 길어져 Find 한 번이 O(n) 이 된 것입니다(크기 기준 합치기와 경로 압축을 확인하세요)";

    static void RunAll()
    {
        Run("initial-singletons", () => Script(1) ?? Script(2) ?? Script(6));

        Run("union-return-values", () =>
            Script(4, 0, 1, 0, 1, 1, 0)            // 같은 쌍을 다시, 순서를 뒤집어서
            ?? Script(3, 2, 2, 0, 0)               // 자기 자신과의 Union
            ?? Script(1, 0, 0)                     // 길드가 하나뿐
            ?? Script(4, 0, 1, 2, 3, 1, 3, 0, 2, 3, 0));

        Run("transitive-links", () =>
            Script(3, 0, 1, 0, 2)                  // 같은 길드를 두 번 합친다: 1 과 2 도 같은 연합이어야 한다
            ?? Script(3, 1, 0, 2, 0)
            ?? Script(5, 0, 1, 1, 2, 2, 3, 3, 4)
            ?? Script(5, 4, 3, 3, 2, 2, 1, 1, 0)
            ?? Script(6, 0, 1, 2, 3, 4, 5, 1, 2, 3, 4)
            ?? Script(6, 0, 3, 1, 4, 2, 5, 5, 4, 3, 4));

        Run("sizes-and-group-count", () =>
            Script(7, 0, 1, 2, 3, 0, 2, 4, 5, 5, 6, 6, 0, 3, 4)
            ?? Script(8, 0, 1, 0, 2, 0, 3, 4, 5, 6, 7, 5, 7, 3, 7, 1, 6)
            ?? Script(5, 0, 4, 4, 0, 1, 3, 3, 1, 2, 2));

        Run("random-vs-labels", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 150; round++)
            {
                int n = 2 + rng.Next(11);
                var ops = new int[2 * (n + 4)];
                for (int i = 0; i < ops.Length; i++) ops[i] = rng.Next(n);
                string e = Script(n, ops);
                if (e != null) return e;
            }
            return null;
        });

        Run("long-chain-ascending", () => Chain(true), Killed, Slow);
        Run("long-chain-descending", () => Chain(false), Killed, Slow);
    }
}

