using System;
using System.Collections.Generic;

public static class BuildPlanner
{
    // rules[i] = (Before, After): Before 가 완공되어야 After 를 지을 수 있다.
    // 모든 규칙을 지키는 건설 순서를 반환한다. 규칙이 순환하면 길이 0 인 배열.
    public static int[] GetBuildOrder(int buildingCount, (int Before, int After)[] rules)
    {
        return Kahn(buildingCount, rules, null) ?? Array.Empty<int>();
    }

    // 한 턴에는 "선행 건물이 모두 이전 턴까지 완공된" 건물을 몇 채든 동시에 지을 수 있다.
    // 모든 건물을 짓는 최소 턴 수를 반환한다. 규칙이 순환하면 -1.
    public static int CountBuildTurns(int buildingCount, (int Before, int After)[] rules)
    {
        var turn = new int[buildingCount];
        if (Kahn(buildingCount, rules, turn) == null) return -1;
        int turns = 0;
        foreach (int t in turn)
            if (t > turns) turns = t;
        return turns;
    }

    // 칸(Kahn)의 알고리즘. 순환이 있으면 null 을 반환한다.
    // turn 이 null 이 아니면 건물마다 가장 이르게 지을 수 있는 턴(1부터)을 채운다.
    private static int[] Kahn(int n, (int Before, int After)[] rules, int[] turn)
    {
        // 1) 진입 차수(아직 완공되지 않은 선행 규칙 수)와 "이 건물이 막고 있는 건물" 목록.
        //    같은 규칙이 여러 번 나오면 양쪽에 똑같이 여러 번 넣는다. 넣은 횟수만큼 다시 빼므로 결과가 같다.
        var indegree = new int[n];
        var unlocks = new List<int>[n];
        foreach (var (before, after) in rules)
        {
            (unlocks[before] ??= new List<int>()).Add(after);
            indegree[after]++;
        }

        // 2) 선행이 하나도 없는 건물부터 큐에 넣는다. 이 건물들은 첫 턴에 지을 수 있다.
        var ready = new Queue<int>();
        for (int b = 0; b < n; b++)
        {
            if (indegree[b] != 0) continue;
            ready.Enqueue(b);
            if (turn != null) turn[b] = 1;
        }

        // 3) 하나를 지을 때마다 그 건물이 막고 있던 건물들의 진입 차수를 1씩 줄이고, 0 이 되면 큐에 넣는다.
        //    진입 차수가 0 이 되는 순간 그 건물의 선행은 전부 처리되었으므로 turn 값도 확정된다.
        var order = new int[n];
        int built = 0;
        while (ready.Count > 0)
        {
            int b = ready.Dequeue();
            order[built++] = b;
            List<int> next = unlocks[b];
            if (next == null) continue;
            foreach (int after in next)
            {
                if (turn != null && turn[b] + 1 > turn[after]) turn[after] = turn[b] + 1;
                if (--indegree[after] == 0) ready.Enqueue(after);
            }
        }

        // 4) 전부 지었으면 성공. 남은 건물이 있으면 그 건물들은 순환에 물려 있거나 순환을 기다린다.
        return built == n ? order : null;
    }
}

