        if (got == null) return ctx + ": GetBuildOrder 가 null 을 반환했습니다(순환이면 길이 0 인 배열)";
        if (wantTurns == -1)
        {
            if (got.Length != 0) return ctx + ": 규칙이 순환하므로 GetBuildOrder 는 길이 0 인 배열이어야 합니다 / 결과 " + Show(got);
