        else
        {
            if (got.Length != n) return ctx + ": 순환이 없으므로 건물 " + n + "개가 모두 들어 있어야 합니다 / 결과 " + Show(got);
            var pos = new int[n];
            for (int i = 0; i < n; i++) pos[i] = -1;
            for (int i = 0; i < n; i++)
            {
                int b = got[i];
                if (b < 0 || b >= n) return ctx + ": 없는 건물 번호 " + b + " 가 들어 있습니다 / 결과 " + Show(got);
                if (pos[b] != -1) return ctx + ": 건물 " + b + " 가 두 번 들어 있습니다 / 결과 " + Show(got);
                pos[b] = i;
            }
            foreach (var (before, after) in snapshot)
                if (pos[before] > pos[after]) return ctx + ": 규칙 " + before + "->" + after + " 를 어겼습니다(" + after + " 가 " + before + " 보다 먼저) / 결과 " + Show(got);
        }
        int turns = BuildPlanner.CountBuildTurns(n, rules);
        for (int i = 0; i < rules.Length; i++)
            if (rules[i] != snapshot[i]) return ctx + ": CountBuildTurns 가 rules 배열을 바꿨습니다";
        if (turns != wantTurns) return ctx + ": CountBuildTurns 기대 " + wantTurns + " / 결과 " + turns;
        return null;
    }

    static (int, int)[] R(params int[] flat)
    {
        var rules = new (int, int)[flat.Length / 2];
        for (int i = 0; i < rules.Length; i++) rules[i] = (flat[2 * i], flat[2 * i + 1]);
        return rules;
    }

    // 작은 입력의 정답 턴 수: 모든 건물을 1턴으로 두고 규칙마다 turn[after] >= turn[before] + 1 을 n 번 반복 적용한다.
    static int SlowTurns(int n, System.Collections.Generic.List<(int, int)> rules)
    {
        var turn = new int[n];
        for (int i = 0; i < n; i++) turn[i] = 1;
        for (int round = 0; round < n; round++)
            foreach (var (a, b) in rules)
                if (turn[a] + 1 > turn[b]) turn[b] = turn[a] + 1;
        int best = 0;
        foreach (int t in turn) if (t > best) best = t;
        return best;
    }

    // rank 가 작은 쪽에서 큰 쪽으로만 규칙을 두면 순환이 없다. rank 순서로 훑으면 정답 턴 수가 나온다.
    static int RankTurns(int n, int[] rank, (int Before, int After)[] rules)
    {
        var byRank = new int[n];
        for (int v = 0; v < n; v++) byRank[rank[v]] = v;
        var start = new int[n + 1];
        foreach (var (a, _) in rules) start[a + 1]++;
        for (int v = 0; v < n; v++) start[v + 1] += start[v];
        var fill = (int[])start.Clone();
        var to = new int[rules.Length];
        foreach (var (a, b) in rules) to[fill[a]++] = b;
        var turn = new int[n];
        int best = 0;
        foreach (int v in byRank)
        {
            if (turn[v] == 0) turn[v] = 1;
            if (turn[v] > best) best = turn[v];
            for (int k = start[v]; k < start[v + 1]; k++)
                if (turn[v] + 1 > turn[to[k]]) turn[to[k]] = turn[v] + 1;
        }
        return best;
    }

    static int[] Shuffled(System.Random rng, int n)
    {
        var a = new int[n];
        for (int i = 0; i < n; i++) a[i] = i;
        for (int i = n - 1; i > 0; i--) { int j = rng.Next(i + 1); int t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }

    const string BigKilled = "이 케이스(건물 10만~20만 개)를 실행하던 중 프로세스가 종료되었습니다. 재귀(DFS)로 순서를 만들면 체인 길이만큼 깊어져 스택 오버플로가 납니다";
    const string BigSlow = "시간 초과(5초): 건물 10만~20만 개 입력이 5초 안에 끝나지 않습니다. 지을 수 있는 건물을 찾으려고 매번 전체 건물이나 전체 규칙을 다시 훑거나 List.RemoveAt(0) 을 큐로 쓰면 O(V²) 이 됩니다";

    static void RunAll()
    {
        Run("example-and-no-rules", () =>
            Check(null, 5, R(0, 1, 0, 2, 1, 3, 2, 3, 3, 4), 4)
            ?? Check(null, 5, R(3, 4, 2, 3, 1, 3, 0, 2, 0, 1), 4)
            ?? Check(null, 4, R(3, 2, 2, 1, 1, 0), 4)
            ?? Check(null, 4, R(0, 1, 1, 2, 2, 1, 0, 3), -1)
            ?? Check(null, 1, R(), 1) ?? Check(null, 4, R(), 1) ?? Check(null, 6, R(4, 1), 2) ?? Check(null, 6, R(5, 0, 3, 2), 2));

        Run("duplicate-rules", () =>
            Check(null, 3, R(0, 1, 0, 1, 1, 2), 3)
            ?? Check(null, 3, R(0, 1, 1, 2, 0, 1, 1, 2, 0, 2, 0, 2), 3)
            ?? Check(null, 4, R(2, 3, 2, 3, 2, 3, 3, 0, 3, 0), 3));

        Run("self-rule", () =>
            Check(null, 1, R(0, 0), -1) ?? Check(null, 3, R(2, 2), -1) ?? Check(null, 4, R(0, 1, 1, 1, 1, 2), -1));

        Run("cycle-with-buildable-part", () =>
            Check(null, 3, R(0, 1, 1, 2, 2, 0), -1)
            ?? Check(null, 5, R(0, 1, 1, 2, 2, 3, 3, 1, 3, 4), -1)
            ?? Check(null, 6, R(0, 1, 2, 3, 3, 4, 4, 2), -1)
            ?? Check(null, 4, R(0, 1, 2, 3, 3, 2), -1));

        Run("turns-longest-chain", () =>
            Check(null, 4, R(0, 3, 0, 1, 1, 2, 2, 3), 4)              // 0->3 은 지름길처럼 보이지만 3 은 2 도 기다린다
            ?? Check(null, 6, R(0, 5, 1, 2, 2, 3, 3, 4, 4, 5), 5)
            ?? Check(null, 5, R(4, 0, 3, 4, 2, 3, 1, 2, 1, 0), 5));

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 400; round++)
            {
                int n = 1 + rng.Next(12);
                int[] rank = Shuffled(rng, n);
                var list = new System.Collections.Generic.List<(int, int)>();
                int m = rng.Next(2 * n + 1);
                for (int e = 0; e < m && n > 1; e++)
                {
                    int a = rng.Next(n), b = rng.Next(n);
                    if (a == b) continue;
                    list.Add(rank[a] < rank[b] ? (a, b) : (b, a));
                }
                bool cyclic = round % 3 == 2 && list.Count > 0;
                if (cyclic) { var e2 = list[rng.Next(list.Count)]; list.Insert(rng.Next(list.Count + 1), (e2.Item2, e2.Item1)); }
                string err = Check(null, n, list.ToArray(), cyclic ? -1 : SlowTurns(n, list));
                if (err != null) return err;
            }
            return null;
        });

        Run("large-chains", () =>
        {
            const int n = 200000;
            var chain = new (int, int)[n - 1];
            for (int i = 0; i < n - 1; i++) chain[i] = (i + 1, i);
            return Check("건물 20만 개가 한 줄: 199999->199998->...->0", n, chain, n)
                ?? Check("건물 20만 개, 규칙 없음", n, new (int, int)[0], 1)
                ?? Check("건물 20만 개가 한 줄: 0->1->...->199999", n, Chain(n), n);
        }, BigKilled, BigSlow, 5000);

        Run("large-random", () =>
        {
            const int n = 100000;
            var rng = new System.Random(7);
            int[] rank = Shuffled(rng, n);
            var rules = new (int, int)[2 * n];
            for (int i = 0; i < rules.Length; i++)
            {
                int a = rng.Next(n), b = rng.Next(n);
                while (a == b) b = rng.Next(n);
                rules[i] = rank[a] < rank[b] ? (a, b) : (b, a);
            }
            string err = Check("건물 10만 개, 무작위 규칙 20만 개(순환 없음)", n, rules, RankTurns(n, rank, rules));
            if (err != null) return err;
            rules[rules.Length - 1] = (rules[0].Item2, rules[0].Item1);
            return Check("건물 10만 개, 무작위 규칙 20만 개 중 마지막 규칙을 첫 규칙의 역방향으로 바꾼 것(순환)", n, rules, -1);
        }, BigKilled, BigSlow, 5000);
    }

    static (int, int)[] Chain(int n)
    {
        var chain = new (int, int)[n - 1];
        for (int i = 0; i < n - 1; i++) chain[i] = (i, i + 1);
        return chain;
    }
}

