using System;

public static class ComboRating
{
    // 콤보 등급: 순서를 유지한 채 골라 데미지가 엄격하게 증가하는 가장 긴 체인의 길이.
    public static int LongestLength(int[] damage)
    {
        return Solve(damage, out _, out _);
    }

    // 그런 체인 하나를 히트 인덱스(오름차순)로 반환한다. 여러 개면 아무거나. 빈 입력이면 길이 0 인 배열.
    public static int[] LongestChain(int[] damage)
    {
        int length = Solve(damage, out int[] tailIndex, out int[] prev);
        var chain = new int[length];
        // 가장 긴 체인의 마지막 히트에서 prev 를 따라 거꾸로 채운다.
        int i = length > 0 ? tailIndex[length - 1] : -1;
        for (int k = length - 1; k >= 0; k--)
        {
            chain[k] = i;
            i = prev[i];
        }
        return chain;
    }

    // tailIndex[k] : 길이 k + 1 인 증가 체인들 중 "마지막 데미지가 가장 작은" 체인의 마지막 히트 인덱스.
    //                damage[tailIndex[0]] < damage[tailIndex[1]] < ... 로 항상 엄격하게 증가한다.
    // prev[i]      : i 로 끝나는 가장 긴 체인에서 i 바로 앞 히트의 인덱스(없으면 -1).
    private static int Solve(int[] damage, out int[] tailIndex, out int[] prev)
    {
        int n = damage.Length;
        tailIndex = new int[n];
        prev = new int[n];
        int length = 0;
        for (int i = 0; i < n; i++)
        {
            int x = damage[i];
            // lower bound: damage[tailIndex[pos]] >= x 인 첫 pos. 같은 값은 이어 붙일 수 없으므로(엄격한 증가) ">=" 에서 멈춘다.
            int lo = 0, hi = length;
            while (lo < hi)
            {
                int mid = lo + (hi - lo) / 2;
                if (damage[tailIndex[mid]] < x) lo = mid + 1;
                else hi = mid;
            }
            prev[i] = lo > 0 ? tailIndex[lo - 1] : -1;   // 길이 lo 인 체인 뒤에 i 를 붙인다
            tailIndex[lo] = i;                            // 길이 lo + 1 의 끝값이 같거나 더 작아졌다
            if (lo == length) length++;
        }
        return length;
    }
}

