        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Emit(id, err);
    }

    // 학습자 코드를 별도 스레드(스택 1MB)에서 실행하고, 케이스 하나가 제한(기본 1초)을 넘기면 그 케이스를 시간 초과로 처리한다.
    public static void Main()
    {
        foreach (string id in Cases)
            System.Console.WriteLine("[FAIL] " + id + " :: 앞선 케이스를 실행하던 중 프로세스가 종료되어 이 케이스는 실행되지 못했습니다");
        var worker = new System.Threading.Thread(RunAll, 1 << 20) { IsBackground = true };
        worker.Start();
        while (!worker.Join(20))
        {
            lock (Gate)
            {
                long now = Clock.ElapsedMilliseconds;
                bool running = Current != null && !Done.Contains(Current);
                if (!(running && now - CurrentStart > CurrentLimit) && now <= TotalLimitMs) continue;
                string stuck = running ? Current : null;
                if (stuck != null) Emit(stuck, CurrentSlow ?? "시간 초과(1초): 반복문이나 재귀가 끝나지 않거나, 시간 복잡도가 제약을 넘습니다");
                foreach (string id in Cases)
                    Emit(id, stuck != null ? "앞선 케이스 " + stuck + " 가 제한 시간을 넘겨 이 케이스는 실행되지 못했습니다" : "전체 제한 시간을 넘겨 실행되지 못했습니다");
                System.Console.Out.Flush();
                System.Environment.Exit(0);
            }
        }
    }

    // 실패 메시지용: 짧은 배열은 내용을, 긴 배열은 길이와 앞부분만 보여 준다.
    static string Show(int[] a)
    {
        if (a == null) return "null";
        if (a.Length <= 16) return "[" + string.Join(",", a) + "]";
        var head = new int[8];
        System.Array.Copy(a, head, 8);
        return "[" + string.Join(",", head) + ",...] (길이 " + a.Length + ")";
    }

    static string Show(long[] a)
    {
        if (a == null) return "null";
        if (a.Length <= 16) return "[" + string.Join(",", a) + "]";
        var head = new long[8];
        System.Array.Copy(a, head, 8);
        return "[" + string.Join(",", head) + ",...] (길이 " + a.Length + ")";
    }

    static bool Same(int[] a, int[] b)
    {
        if (a.Length != b.Length) return false;
        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return false;
        return true;
    }

    // 체인은 유효하기만 하면 무엇이든 통과다: 길이가 want, 인덱스가 범위 안에서 오름차순, 데미지가 엄격하게 증가.
    static string Check(string label, int[] damage, int want)
    {
        var copy = (int[])damage.Clone();
        string ctx = label ?? ("damage = " + Show(damage));
        int len = ComboRating.LongestLength(damage);
        if (!Same(damage, copy)) return ctx + ": LongestLength 가 damage 배열을 바꿨습니다";
        if (len != want) return ctx + ": LongestLength 기대 " + want + " / 결과 " + len;
        int[] chain = ComboRating.LongestChain(damage);
        if (!Same(damage, copy)) return ctx + ": LongestChain 이 damage 배열을 바꿨습니다";
        if (chain == null) return ctx + ": LongestChain 이 null 을 반환했습니다(빈 입력이면 길이 0 인 배열)";
        if (chain.Length != want) return ctx + ": LongestChain 의 길이 기대 " + want + " / 결과 " + chain.Length + " " + Show(chain);
        for (int k = 0; k < chain.Length; k++)
        {
            if (chain[k] < 0 || chain[k] >= damage.Length) return ctx + ": LongestChain 에 범위 밖 인덱스 " + chain[k] + " 가 있습니다 / 결과 " + Show(chain);
            if (k == 0) continue;
            if (chain[k] <= chain[k - 1]) return ctx + ": LongestChain 의 인덱스가 오름차순이 아닙니다(" + chain[k - 1] + " 다음 " + chain[k] + ") / 결과 " + Show(chain);
            if (damage[chain[k]] <= damage[chain[k - 1]]) return ctx + ": 데미지가 엄격하게 증가하지 않습니다(damage[" + chain[k - 1] + "] = " + damage[chain[k - 1]] + ", damage[" + chain[k] + "] = " + damage[chain[k]] + ") / 결과 " + Show(chain);
        }
        return null;
    }

    static int[] A(params int[] a) => a;

    // 작은 입력의 정답: best[i] = i 로 끝나는 가장 긴 엄격 증가 체인의 길이 (O(n^2) 정의 그대로).
    static int Quadratic(int[] a)
    {
        var best = new int[a.Length];
        int answer = 0;
        for (int i = 0; i < a.Length; i++)
        {
            best[i] = 1;
            for (int j = 0; j < i; j++)
                if (a[j] < a[i] && best[j] + 1 > best[i]) best[i] = best[j] + 1;
            if (best[i] > answer) answer = best[i];
        }
        return answer;
    }

    // 큰 입력의 정답: 값을 순위로 압축한 뒤, "순위가 더 작은 값으로 끝나는 체인 중 최대 길이"를 펜윅 트리로 구한다.
    static int FenwickReference(int[] a)
    {
        int n = a.Length;
        var sorted = (int[])a.Clone();
        System.Array.Sort(sorted);
        int m = 0;
        for (int i = 0; i < n; i++) if (m == 0 || sorted[i] != sorted[m - 1]) sorted[m++] = sorted[i];
        var tree = new int[m + 1];
        int answer = 0;
        foreach (int x in a)
        {
            int r = System.Array.BinarySearch(sorted, 0, m, x) + 1;   // 1-based 순위, 값이 서로 달라 위치가 하나뿐이다
            int best = 0;
            for (int k = r - 1; k > 0; k -= k & -k) if (tree[k] > best) best = tree[k];
            best++;
            for (int k = r; k <= m; k += k & -k) if (tree[k] < best) tree[k] = best;
            if (best > answer) answer = best;
        }
        return answer;
    }

    const string BigSlow = "시간 초과(1초): 히트 20만 개 입력이 끝나지 않습니다. i 마다 앞의 모든 j 를 보는 DP(비교 약 200억 번)나 체인을 List.Insert(0, …) 로 앞에 끼워 넣는 복원(길이 20만이면 원소 이동 약 200억 번)은 O(n²) 입니다";
    const string BigKilled = "이 케이스(히트 20만 개)를 실행하던 중 프로세스가 종료되었습니다. 체인을 재귀로 복원하면 길이 20만에서 스택이 넘칩니다";

    static void RunAll()
    {
        Run("example", () =>
            Check(null, A(30, 10, 20, 50, 40, 45, 15), 4)
            ?? Check(null, A(3, 10, 2, 1, 20, 4, 6, 7), 4)
            ?? Check(null, A(5, 5, 5), 1)
            ?? Check(null, A(2, 2, 3, 3, 4), 3));

        Run("empty-single-monotone", () =>
            Check(null, A(), 0) ?? Check(null, A(7), 1) ?? Check(null, A(-3), 1)
            ?? Check(null, A(1, 2, 3, 4, 5, 6), 6) ?? Check(null, A(6, 5, 4, 3, 2, 1), 1) ?? Check(null, A(-1, -2), 1));

        Run("duplicates-strict", () =>
            Check(null, A(4, 4), 1) ?? Check(null, A(1, 2, 2, 2, 3), 3) ?? Check(null, A(3, 1, 1, 2, 2, 3, 3), 3)
            ?? Check(null, A(9, 9, 9, 9, 9, 9, 9, 9), 1) ?? Check(null, A(1, 3, 2, 3, 2, 3, 4), 4));

        Run("tails-is-not-the-chain", () =>
            Check(null, A(3, 4, 1), 2) ?? Check(null, A(30, 10, 20, 50, 40, 45, 15), 4)
            ?? Check(null, A(2, 5, 3, 7, 11, 8, 10, 13, 6), 6) ?? Check(null, A(10, 20, 30, 1, 2), 3) ?? Check(null, A(5, 6, 7, 8, 1, 2, 3), 4));

        Run("extreme-values", () =>
            Check(null, A(int.MinValue, int.MaxValue), 2)
            ?? Check(null, A(1, int.MaxValue), 2)
            ?? Check(null, A(int.MaxValue, int.MaxValue), 1)
            ?? Check(null, A(int.MinValue, int.MinValue, 0), 2)
            ?? Check(null, A(int.MaxValue, int.MinValue, 0, int.MaxValue), 3)
            ?? Check(null, A(0, int.MinValue, int.MinValue + 1, -1, int.MaxValue - 1, int.MaxValue), 5));

        Run("random-vs-quadratic", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 600; round++)
            {
                int n = rng.Next(31);
                var a = new int[n];
                int range = round % 3 == 0 ? 4 : round % 3 == 1 ? 40 : 0;
                for (int i = 0; i < n; i++) a[i] = range > 0 ? rng.Next(-range, range) : rng.Next(int.MinValue, int.MaxValue);
                string err = Check(null, a, Quadratic(a));
                if (err != null) return err;
            }
            return null;
        });

        Run("large-random", () =>
        {
            const int n = 200000;
            var rng = new System.Random(7);
            var a = new int[n];
            for (int i = 0; i < n; i++) a[i] = rng.Next(int.MinValue, int.MaxValue);
            string err = Check("히트 20만 개, 데미지가 int 전 범위의 무작위 값", a, FenwickReference(a));
            if (err != null) return err;
            for (int i = 0; i < n; i++) a[i] = rng.Next(1000);
            return Check("히트 20만 개, 데미지가 0~999 의 무작위 값(중복이 많음)", a, FenwickReference(a));
        }, BigKilled, BigSlow);

        Run("large-monotone", () =>
        {
            const int n = 200000;
            var a = new int[n];
            for (int i = 0; i < n; i++) a[i] = i - 100000;
            string err = Check("히트 20만 개, 데미지가 -100000, -99999, ... 로 1씩 증가", a, n);
            if (err != null) return err;
            for (int i = 0; i < n; i++) a[i] = n - i;
            err = Check("히트 20만 개, 데미지가 200000, 199999, ... 로 감소", a, 1);
            if (err != null) return err;
            for (int i = 0; i < n; i++) a[i] = (i / 500) * 1000 + (499 - i % 500);   // 500개씩 감소하는 블록 400개, 블록끼리는 증가
            return Check("히트 20만 개, 블록 400개(블록 안은 감소, 블록끼리는 증가)", a, 400);
        }, BigKilled, BigSlow);
    }
}

