problems.solutionCode:
using System;

public static class LaneDamage
{
    // hits[i] = (From, To, Amount): From ~ To 칸(양 끝 포함)에 Amount 만큼 피해를 준다. 음수는 회복.
    // 칸별 누적 피해를 반환한다: result[c] = c 를 덮는 모든 hit 의 Amount 합.
    public static long[] PerCell(int laneLength, (int From, int To, int Amount)[] hits)
    {
        // 차분 배열: diff[c] = cell[c] - cell[c - 1]. 구간 [From, To] 에 더하기는 양 끝 두 칸만 바꾼다.
        // 크기를 laneLength + 1 로 두면 To == laneLength - 1 일 때의 diff[To + 1] 도 검사 없이 기록할 수 있다.
        var diff = new long[laneLength + 1];
        foreach (var (from, to, amount) in hits)
        {
            diff[from] += amount;
            diff[to + 1] -= amount;
        }

        // 차분 배열의 누적 합이 곧 칸별 값이다. 칸 하나가 int 범위를 넘을 수 있으므로 long 으로 더한다.
        var cell = new long[laneLength];
        long running = 0;
        for (int c = 0; c < laneLength; c++)
        {
            running += diff[c];
            cell[c] = running;
        }
        return cell;
    }

    // queries[q] = (From, To): 웨이브가 끝난 뒤 From ~ To 칸(양 끝 포함)의 누적 피해 합.
    public static long[] RangeTotals(int laneLength, (int From, int To, int Amount)[] hits, (int From, int To)[] queries)
    {
        long[] cell = PerCell(laneLength, hits);

        // 누적 합: prefix[k] = cell[0] + ... + cell[k - 1], prefix[0] = 0.
        // 그러면 [From, To] 의 합은 prefix[To + 1] - prefix[From] 이고, From == 0 도 특별 처리가 필요 없다.
        var prefix = new long[laneLength + 1];
        for (int c = 0; c < laneLength; c++)
            prefix[c + 1] = prefix[c] + cell[c];

        var result = new long[queries.Length];
        for (int q = 0; q < queries.Length; q++)
            result[q] = prefix[queries[q].To + 1] - prefix[queries[q].From];
        return result;
    }
}

