public static class __Judge
{
    static readonly string[] Cases = { "example-and-empty", "hit-reaches-last-cell", "query-endpoints", "negative-and-zero", "overflow-needs-long", "random-vs-naive", "large-lane" };
    const int CaseLimitMs = 1000, TotalLimitMs = 2600;
    static readonly object Gate = new object();
    static readonly System.Collections.Generic.HashSet<string> Done = new System.Collections.Generic.HashSet<string>();
    static readonly System.Diagnostics.Stopwatch Clock = System.Diagnostics.Stopwatch.StartNew();
    static string Current, CurrentSlow;
    static long CurrentStart, CurrentLimit;

    static void Emit(string id, string err)
    {
        lock (Gate)
        {
            if (!Done.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    // 같은 케이스 이름은 마지막 줄이 결과다. 스택 오버플로는 catch 할 수 없이 프로세스를 끝내므로,
    // 실패 사유(ifKilled)를 먼저 출력해 두고 끝까지 실행되면 실제 결과가 그 뒤에 출력된다.
    static void Run(string id, System.Func<string> body, string ifKilled = null, string ifSlow = null, int limitMs = CaseLimitMs)
    {
        lock (Gate)
        {
            Current = id; CurrentSlow = ifSlow; CurrentStart = Clock.ElapsedMilliseconds; CurrentLimit = limitMs;
            System.Console.WriteLine("[FAIL] " + id + " :: " + (ifKilled ?? "이 케이스를 실행하던 중 프로세스가 종료되었습니다(재귀가 끝나지 않거나 너무 깊어 스택이 넘치면 이렇게 됩니다)"));
        }
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Emit(id, err);
    }

    // 학습자 코드를 별도 스레드(스택 1MB)에서 실행하고, 케이스 하나가 제한(기본 1초)을 넘기면 그 케이스를 시간 초과로 처리한다.
    public static void Main()
    {
        foreach (string id in Cases)
            System.Console.WriteLine("[FAIL] " + id + " :: 앞선 케이스를 실행하던 중 프로세스가 종료되어 이 케이스는 실행되지 못했습니다");
        var worker = new System.Threading.Thread(RunAll, 1 << 20) { IsBackground = true };
        worker.Start();
        while (!worker.Join(20))
        {
            lock (Gate)
            {
                long now = Clock.ElapsedMilliseconds;
                bool running = Current != null && !Done.Contains(Current);
                if (!(running && now - CurrentStart > CurrentLimit) && now <= TotalLimitMs) continue;
                string stuck = running ? Current : null;
                if (stuck != null) Emit(stuck, CurrentSlow ?? "시간 초과(1초): 반복문이나 재귀가 끝나지 않거나, 시간 복잡도가 제약을 넘습니다");
                foreach (string id in Cases)
                    Emit(id, stuck != null ? "앞선 케이스 " + stuck + " 가 제한 시간을 넘겨 이 케이스는 실행되지 못했습니다" : "전체 제한 시간을 넘겨 실행되지 못했습니다");
                System.Console.Out.Flush();
                System.Environment.Exit(0);
            }
        }
    }

    // 실패 메시지용: 짧은 배열은 내용을, 긴 배열은 길이와 앞부분만 보여 준다.
    static string Show(int[] a)
    {
        if (a == null) return "null";
        if (a.Length <= 16) return "[" + string.Join(",", a) + "]";
        var head = new int[8];
        System.Array.Copy(a, head, 8);
        return "[" + string.Join(",", head) + ",...] (길이 " + a.Length + ")";
    }

    static string Show(long[] a)
    {
        if (a == null) return "null";
        if (a.Length <= 16) return "[" + string.Join(",", a) + "]";
        var head = new long[8];
        System.Array.Copy(a, head, 8);
        return "[" + string.Join(",", head) + ",...] (길이 " + a.Length + ")";
    }

    static string ShowHits((int From, int To, int Amount)[] hits)
    {
        if (hits.Length == 0) return "(없음)";
        var sb = new System.Text.StringBuilder();
        int shown = hits.Length <= 6 ? hits.Length : 3;
        for (int i = 0; i < shown; i++) sb.Append(i > 0 ? " " : "").Append("[" + hits[i].From + "~" + hits[i].To + "]" + hits[i].Amount);
        if (hits.Length > shown) sb.Append(" ... (" + hits.Length + "개)");
        return sb.ToString();
    }

    // 정의 그대로 계산하는 정답(작은 입력용): 히트마다 덮는 칸을 하나씩 더한다.
    static long[] NaiveCells(int n, (int From, int To, int Amount)[] hits)
    {
        var cell = new long[n];
        foreach (var (f, t, a) in hits) for (int c = f; c <= t; c++) cell[c] += a;
        return cell;
    }

    static long[] NaiveRanges(long[] cell, (int From, int To)[] queries)
    {
        var r = new long[queries.Length];
        for (int q = 0; q < queries.Length; q++) for (int c = queries[q].From; c <= queries[q].To; c++) r[q] += cell[c];
        return r;
    }

    // 큰 입력용 정답: 차분 배열과 누적 합(작은 입력에서 위의 정의 그대로의 계산과 같음을 확인해 둔 구현).
    static long[] FastCells(int n, (int From, int To, int Amount)[] hits)
    {
        var d = new long[n + 1];
        foreach (var (f, t, a) in hits) { d[f] += a; d[t + 1] -= a; }
        var cell = new long[n];
        long run = 0;
        for (int c = 0; c < n; c++) { run += d[c]; cell[c] = run; }
        return cell;
    }

    static long[] FastRanges(long[] cell, (int From, int To)[] queries)
    {
        var p = new long[cell.Length + 1];
        for (int c = 0; c < cell.Length; c++) p[c + 1] = p[c] + cell[c];
        var r = new long[queries.Length];
        for (int q = 0; q < queries.Length; q++) r[q] = p[queries[q].To + 1] - p[queries[q].From];
        return r;
    }

    static string Check(string label, int n, (int From, int To, int Amount)[] hits, (int From, int To)[] queries, long[] wantCells = null, long[] wantRanges = null)
    {
        bool small = (long)n * (hits.Length + 1) <= 5000000L;
        if (wantCells == null) wantCells = small ? NaiveCells(n, hits) : FastCells(n, hits);
        if (wantRanges == null) wantRanges = small ? NaiveRanges(wantCells, queries) : FastRanges(wantCells, queries);
        string ctx = label ?? ("칸 " + n + "개, 히트 " + ShowHits(hits));
        var hitsCopy = ((int From, int To, int Amount)[])hits.Clone();
        var queriesCopy = ((int From, int To)[])queries.Clone();

        long[] cells = LaneDamage.PerCell(n, hits);
        for (int i = 0; i < hits.Length; i++) if (hits[i] != hitsCopy[i]) return ctx + ": PerCell 이 hits 배열을 바꿨습니다";
        if (cells == null) return ctx + ": PerCell 이 null 을 반환했습니다";
        if (cells.Length != n) return ctx + ": PerCell 결과 길이 기대 " + n + " / 결과 " + cells.Length;
        for (int c = 0; c < n; c++)
            if (cells[c] != wantCells[c])
                return ctx + ": PerCell 칸 " + c + " 기대 " + wantCells[c] + " / 결과 " + cells[c] + (n <= 16 ? " (전체 기대 " + Show(wantCells) + " / 결과 " + Show(cells) + ")" : "");

        long[] got = LaneDamage.RangeTotals(n, hits, queries);
        for (int i = 0; i < hits.Length; i++) if (hits[i] != hitsCopy[i]) return ctx + ": RangeTotals 가 hits 배열을 바꿨습니다";
        for (int i = 0; i < queries.Length; i++) if (queries[i] != queriesCopy[i]) return ctx + ": RangeTotals 가 queries 배열을 바꿨습니다";
        if (got == null) return ctx + ": RangeTotals 가 null 을 반환했습니다(질의가 없으면 길이 0 인 배열)";
        if (got.Length != queries.Length) return ctx + ": RangeTotals 결과 길이 기대 " + queries.Length + " / 결과 " + got.Length;
        for (int q = 0; q < queries.Length; q++)
            if (got[q] != wantRanges[q])
                return ctx + ": RangeTotals 질의 " + queries[q].From + "~" + queries[q].To + " 기대 " + wantRanges[q] + " / 결과 " + got[q];
        return null;
    }

    static (int, int, int)[] H(params int[] f)
    {
        var h = new (int, int, int)[f.Length / 3];
        for (int i = 0; i < h.Length; i++) h[i] = (f[3 * i], f[3 * i + 1], f[3 * i + 2]);
        return h;
    }

    static (int, int)[] Q(params int[] f)
    {
        var q = new (int, int)[f.Length / 2];
        for (int i = 0; i < q.Length; i++) q[i] = (f[2 * i], f[2 * i + 1]);
        return q;
    }

    static (int, int, int)[] Repeat(int count, int from, int to, int amount)
    {
        var h = new (int, int, int)[count];
        for (int i = 0; i < count; i++) h[i] = (from, to, amount);
        return h;
    }

    static (int, int, int)[] Concat((int, int, int)[] a, (int, int, int)[] b)
    {
        var r = new (int, int, int)[a.Length + b.Length];
        a.CopyTo(r, 0); b.CopyTo(r, a.Length);
        return r;
    }

    static void RunAll()
    {
        Run("example-and-empty", () =>
            Check(null, 10, H(1, 4, 10, 3, 7, 5, 0, 2, -3), Q(0, 9, 3, 3, 2, 5),
                  new long[] { -3, 7, 7, 15, 15, 5, 5, 5, 0, 0 }, new long[] { 56, 15, 42 })
            ?? Check(null, 6, H(), Q(0, 5, 2, 3), new long[6], new long[2])
            ?? Check(null, 5, H(0, 3, 9), Q()));

        Run("hit-reaches-last-cell", () =>
            Check(null, 1, H(0, 0, 7), Q(0, 0))
            ?? Check(null, 5, H(2, 4, 1, 4, 4, 2, 0, 4, 3), Q(4, 4, 0, 4, 3, 4))
            ?? Check(null, 3, H(2, 2, 5, 0, 2, 1), Q(2, 2, 1, 2)));

        Run("query-endpoints", () =>
            Check(null, 7, H(0, 0, 1, 1, 1, 10, 5, 5, 100, 2, 4, 1000), Q(0, 0, 6, 6, 0, 6, 1, 1, 4, 5, 0, 4, 1, 6, 5, 5))
            ?? Check(null, 3, H(0, 1, 3, 1, 1, 4), Q(0, 0, 1, 1, 0, 1, 2, 2, 0, 2)));

        Run("negative-and-zero", () =>
            Check(null, 6, H(0, 4, 10, 1, 3, -10, 2, 2, 0), Q(0, 5, 1, 3, 2, 2, 0, 4))
            ?? Check(null, 5, H(0, 3, -5, 0, 1, -7, 3, 3, 12), Q(0, 4, 0, 1, 3, 3))
            ?? Check(null, 4, H(0, 2, 1000000, 0, 2, -1000000), Q(0, 3, 1, 2)));

        Run("overflow-needs-long", () =>
            Check(null, 6, Repeat(3000, 0, 4, 1000000), Q(0, 5, 2, 2))                        // 0~4 칸마다 30억, 전체 150억
            ?? Check(null, 4, Concat(Repeat(3000, 0, 2, 1000000), Repeat(3000, 1, 1, -1000000)), Q(0, 3, 1, 1))
            ?? Check(null, 5, Repeat(2500, 1, 3, -1000000), Q(0, 4, 1, 1))                    // 1~3 칸마다 -25억
            ?? Check(null, 11, Repeat(200000, 0, 9, 1000000), Q(0, 10, 3, 6)));                // 0~9 칸마다 2,000억

        Run("random-vs-naive", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 500; round++)
            {
                int n = 1 + rng.Next(20);
                var hits = new (int, int, int)[rng.Next(16)];
                for (int i = 0; i < hits.Length; i++)
                {
                    int a = rng.Next(n), b = rng.Next(n);
                    hits[i] = (System.Math.Min(a, b), System.Math.Max(a, b), rng.Next(-1000000, 1000001));
                }
                var qs = new (int, int)[rng.Next(16)];
                for (int i = 0; i < qs.Length; i++) { int a = rng.Next(n), b = rng.Next(n); qs[i] = (System.Math.Min(a, b), System.Math.Max(a, b)); }
                string err = Check(null, n, hits, qs);
                if (err != null) return err;
            }
            return null;
        });

        Run("large-lane", () =>
        {
            const int n = 200000;
            var rng = new System.Random(7);
            var hits = new (int, int, int)[200000];
            for (int i = 0; i < hits.Length; i++) { int a = rng.Next(n), b = rng.Next(n); hits[i] = (System.Math.Min(a, b), System.Math.Max(a, b), rng.Next(-1000000, 1000001)); }
            var qs = new (int, int)[200000];
            for (int i = 0; i < qs.Length; i++) { int a = rng.Next(n), b = rng.Next(n); qs[i] = (System.Math.Min(a, b), System.Math.Max(a, b)); }
            string err = Check("칸 20만 개, 무작위 구간 히트 20만 개, 무작위 질의 20만 개", n, hits, qs);
            if (err != null) return err;
            var full = Repeat(200000, 0, n - 1, 1000000);
            var allCells = new long[n];
            for (int c = 0; c < n; c++) allCells[c] = 200000L * 1000000L;
            return Check("칸 20만 개 전체를 덮는 1,000,000 피해 히트 20만 개(칸마다 2×10^11, 전체 합 4×10^16)", n, full, Q(0, n - 1, 0, 0, n - 1, n - 1, 1, n - 2),
                         allCells, new long[] { 40000000000000000L, 200000000000L, 200000000000L, 39999600000000000L });
        }, null, "시간 초과(1초): 칸 20만 개, 히트 20만 개, 질의 20만 개가 끝나지 않습니다. 히트마다 덮는 칸을 하나씩 더하거나 질의마다 칸을 하나씩 더하면 평균 수만 칸 × 20만 번입니다. 차분 배열과 누적 합을 쓰세요");
    }
}

