problems.solutionCode:
using System;

// 던전 생성기가 만든 맵에서 입구(왼쪽 위)부터 보스방(오른쪽 아래)까지
// 오른쪽 또는 아래로만 한 칸씩 움직이는 서로 다른 경로의 수를 센다.
public sealed class RouteCounter
{
    // 반환값은 min(실제 경로 수, Cap) 이다. 결과 화면은 Cap 을 "10^18 이상"으로 표시한다.
    public const long Cap = 1_000_000_000_000_000_000;

    // 생성기가 맵 수천 개를 연달아 검사하므로 맵마다 새로 할당하지 않고 재사용하는 한 줄 버퍼.
    // 칸 (r, c) 의 값은 _ways[c + 1] 에 둔다. _ways[0] 은 0 번 열 왼쪽의 가상 칸으로 항상 0 이다.
    // [수정 3] int 로는 18×18 빈 맵(23억 가지)부터 넘친다. long 으로 바꾸고 아래에서 Cap 으로 포화시킨다.
    private long[] _ways = new long[16];

    // map[r][c] == '#' 이면 벽, '.' 이면 통로. 모든 줄의 길이는 같다.
    public long CountRoutes(string[] map)
    {
        int rows = map.Length, cols = map[0].Length;
        // [수정 2] 인덱스가 c + 1 까지 쓰이므로 버퍼는 cols + 1 칸이 필요하다(cols 칸이면 마지막 열에서 범위를 벗어난다).
        if (_ways.Length < cols + 1) _ways = new long[cols + 1];
        Array.Clear(_ways, 0, cols + 1);   // 이전 맵이 남긴 값을 지운다
        _ways[1] = 1;   // 입구 위의 가상 칸에서 한 가지 경로가 내려온다

        for (int r = 0; r < rows; r++)
        {
            string line = map[r];
            // [수정 1] 왼쪽 → 오른쪽. _ways[c] 는 이번 줄에서 이미 갱신된 "왼쪽 칸" 이어야 하고,
            //          _ways[c + 1] 은 아직 갱신되지 않은 "위 칸"(이전 줄의 값)이어야 한다.
            for (int c = 0; c < cols; c++)
            {
                if (line[c] == '#')
                {
                    _ways[c + 1] = 0;
                    continue;
                }
                // 두 값 모두 Cap(10^18) 이하라 합은 2×10^18 이하로 long.MaxValue(약 9.2×10^18)를 넘지 않는다.
                long sum = _ways[c + 1] + _ways[c];
                _ways[c + 1] = sum > Cap ? Cap : sum;
            }
        }
        return _ways[cols];
    }
}

