{{USER_CODE}}

public static class __Judge
{
    static readonly string[] Cases = { "open-maps", "walls-and-blocked-ends", "wide-maps", "beyond-int", "cap-saturation", "buffer-reuse", "random-vs-reference", "large-maps" };
    const int CaseLimitMs = 1000, TotalLimitMs = 2600;
    static readonly object Gate = new object();
    static readonly System.Collections.Generic.HashSet<string> Done = new System.Collections.Generic.HashSet<string>();
    static readonly System.Diagnostics.Stopwatch Clock = System.Diagnostics.Stopwatch.StartNew();
    static string Current, CurrentSlow;
    static long CurrentStart, CurrentLimit;

    static void Emit(string id, string err)
    {
        lock (Gate)
        {
            if (!Done.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    // 같은 케이스 이름은 마지막 줄이 결과다. 스택 오버플로는 catch 할 수 없이 프로세스를 끝내므로,
    // 실패 사유(ifKilled)를 먼저 출력해 두고 끝까지 실행되면 실제 결과가 그 뒤에 출력된다.
    static void Run(string id, System.Func<string> body, string ifKilled = null, string ifSlow = null, int limitMs = CaseLimitMs)
    {
        lock (Gate)
        {
            Current = id; CurrentSlow = ifSlow; CurrentStart = Clock.ElapsedMilliseconds; CurrentLimit = limitMs;
            System.Console.WriteLine("[FAIL] " + id + " :: " + (ifKilled ?? "이 케이스를 실행하던 중 프로세스가 종료되었습니다(재귀가 끝나지 않거나 너무 깊어 스택이 넘치면 이렇게 됩니다)"));
        }
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Emit(id, err);
    }

    // 학습자 코드를 별도 스레드(스택 1MB)에서 실행하고, 케이스 하나가 제한(기본 1초)을 넘기면 그 케이스를 시간 초과로 처리한다.
    public static void Main()
    {
        foreach (string id in Cases)
            System.Console.WriteLine("[FAIL] " + id + " :: 앞선 케이스를 실행하던 중 프로세스가 종료되어 이 케이스는 실행되지 못했습니다");
        var worker = new System.Threading.Thread(RunAll, 1 << 20) { IsBackground = true };
        worker.Start();
        while (!worker.Join(20))
        {
            lock (Gate)
            {
                long now = Clock.ElapsedMilliseconds;
                bool running = Current != null && !Done.Contains(Current);
                if (!(running && now - CurrentStart > CurrentLimit) && now <= TotalLimitMs) continue;
                string stuck = running ? Current : null;
                if (stuck != null) Emit(stuck, CurrentSlow ?? "시간 초과(1초): 반복문이나 재귀가 끝나지 않거나, 시간 복잡도가 제약을 넘습니다");
                foreach (string id in Cases)
                    Emit(id, stuck != null ? "앞선 케이스 " + stuck + " 가 제한 시간을 넘겨 이 케이스는 실행되지 못했습니다" : "전체 제한 시간을 넘겨 실행되지 못했습니다");
                System.Console.Out.Flush();
                System.Environment.Exit(0);
            }
        }
    }

    // 실패 메시지용: 짧은 배열은 내용을, 긴 배열은 길이와 앞부분만 보여 준다.
    static string Show(int[] a)
    {
        if (a == null) return "null";
        if (a.Length <= 16) return "[" + string.Join(",", a) + "]";
        var head = new int[8];
        System.Array.Copy(a, head, 8);
        return "[" + string.Join(",", head) + ",...] (길이 " + a.Length + ")";
    }

    static string Show(long[] a)
    {
        if (a == null) return "null";
        if (a.Length <= 16) return "[" + string.Join(",", a) + "]";
        var head = new long[8];
        System.Array.Copy(a, head, 8);
        return "[" + string.Join(",", head) + ",...] (길이 " + a.Length + ")";
    }

    static string[] Open(int rows, int cols)
    {
        var m = new string[rows];
        for (int r = 0; r < rows; r++) m[r] = new string('.', cols);
        return m;
    }

    static string[] M(params string[] rows) => rows;

    static string Describe(string[] map, string label)
    {
        if (label != null) return label;
        if (map.Length <= 6 && map[0].Length <= 12) return "맵 " + string.Join("/", map);
        return "맵 " + map.Length + "×" + map[0].Length;
    }

    // 정답: 칸마다 실제 경로 수를 BigInteger 로 정확히 센 뒤 Cap 과 비교한다(작은 맵용).
    static long Reference(string[] map)
    {
        int rows = map.Length, cols = map[0].Length;
        var ways = new System.Numerics.BigInteger[rows, cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                if (map[r][c] == '#') continue;
                if (r == 0 && c == 0) { ways[r, c] = 1; continue; }
                var v = System.Numerics.BigInteger.Zero;
                if (r > 0) v += ways[r - 1, c];
                if (c > 0) v += ways[r, c - 1];
                ways[r, c] = v;
            }
        var exact = ways[rows - 1, cols - 1];
        return exact > RouteCounter.Cap ? RouteCounter.Cap : (long)exact;
    }

    static string Check(RouteCounter rc, string[] map, long want, string label = null)
    {
        var rowsCopy = (string[])map.Clone();
        long got;
        try { got = rc.CountRoutes(map); }
        catch (System.Exception e) { return Describe(map, label) + ": 예외 발생 " + e.GetType().Name; }
        for (int r = 0; r < map.Length; r++) if (!ReferenceEquals(map[r], rowsCopy[r])) return Describe(map, label) + ": map 배열을 바꿨습니다";
        return got == want ? null : Describe(map, label) + ": 기대 " + want + " / 결과 " + got;
    }

    static string CheckAll(RouteCounter rc, params string[][] maps)
    {
        foreach (var m in maps) { string e = Check(rc, m, Reference(m)); if (e != null) return e; }
        return null;
    }

    static string[] RandomMap(System.Random rng, int rows, int cols, int wallPercent)
    {
        var m = new string[rows];
        var chars = new char[cols];
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++) chars[c] = rng.Next(100) < wallPercent ? '#' : '.';
            m[r] = new string(chars);
        }
        return m;
    }

    const long Cap = RouteCounter.Cap;

    static void RunAll()
    {
        Run("open-maps", () =>
        {
            var rc = new RouteCounter();
            return Check(rc, Open(1, 1), 1) ?? Check(rc, Open(1, 3), 1) ?? Check(rc, Open(1, 5), 1) ?? Check(rc, Open(5, 1), 1) ?? Check(rc, Open(1, 15), 1)
                ?? Check(rc, Open(2, 2), 2) ?? Check(rc, Open(3, 3), 6) ?? Check(rc, Open(4, 5), 35) ?? Check(rc, Open(5, 4), 35)
                ?? Check(rc, Open(6, 6), 252) ?? Check(rc, Open(10, 10), 48620) ?? Check(rc, Open(15, 15), 40116600, "빈 맵 15×15");
        });

        Run("walls-and-blocked-ends", () =>
        {
            var rc = new RouteCounter();
            return Check(rc, M("#"), 0) ?? Check(rc, M("#..", "...", "..."), 0) ?? Check(rc, M("...", "...", "..#"), 0)
                ?? Check(rc, M("....", "####", "...."), 0) ?? Check(rc, M(".#.", ".#.", "..."), 1)
                ?? CheckAll(rc, M("...", ".#.", "..."), M("..#.", "....", "#...", "..#."), M(".....", ".#.#.", ".....", ".#.#.", "....."), M("..", "#.", ".."));
        });

        Run("wide-maps", () =>
        {
            var rc = new RouteCounter();
            return Check(rc, Open(1, 16), 1, "빈 맵 1×16") ?? Check(rc, Open(2, 16), 16, "빈 맵 2×16") ?? Check(rc, Open(2, 20), 20, "빈 맵 2×20")
                ?? Check(rc, Open(3, 40), 820, "빈 맵 3×40")
                ?? CheckAll(rc, M("....#...........", "..........#.....", "#..............."), M("..................#.", "....#..............."));
        });

        Run("beyond-int", () =>
        {
            var rc = new RouteCounter();
            return Check(rc, Open(40, 12), 37353738800L, "빈 맵 40×12") ?? Check(rc, Open(30, 15), 78378960360L, "빈 맵 30×15")
                ?? Check(rc, Open(25, 15), 9669554100L, "빈 맵 25×15")
                ?? Check(rc, Open(18, 18), 2333606220L, "빈 맵 18×18") ?? Check(rc, Open(12, 40), 37353738800L, "빈 맵 12×40");
        });

        Run("cap-saturation", () =>
        {
            var rc = new RouteCounter();
            return Check(rc, Open(32, 32), 465428353255261088L, "빈 맵 32×32") ?? Check(rc, Open(33, 32), 916312070471295267L, "빈 맵 33×32")
                ?? Check(rc, Open(33, 33), Cap, "빈 맵 33×33(실제 1,832,624,140,942,590,534 가지)")
                ?? Check(rc, Open(34, 34), Cap, "빈 맵 34×34(실제 7,219,428,434,016,265,740 가지)")
                ?? Check(rc, Open(35, 35), Cap, "빈 맵 35×35(실제 약 2.8×10^19 가지, long 범위 밖)")
                ?? Check(rc, Open(70, 70), Cap, "빈 맵 70×70(실제 약 2.4×10^40 가지)");
        });

        Run("buffer-reuse", () =>
        {
            var rc = new RouteCounter();
            var rng = new System.Random(11);
            int[] widths = { 20, 5, 1, 40, 3, 17, 2, 33, 6, 33, 4 };
            foreach (int w in widths)
            {
                string[] m = RandomMap(rng, 3 + rng.Next(6), w, 15);
                string e = Check(rc, m, Reference(m), "같은 RouteCounter 로 폭 20, 5, 1, 40, 3, 17, 2, 33, 6, 33, 4 맵을 차례로 검사하던 중 폭 " + w + " 맵");
                if (e != null) return e;
            }
            return null;
        });

        Run("random-vs-reference", () =>
        {
            var rc = new RouteCounter();
            var rng = new System.Random(20261122);
            for (int round = 0; round < 300; round++)
            {
                int rows = 1 + rng.Next(round < 200 ? 12 : 70), cols = 1 + rng.Next(round < 200 ? 12 : 70);
                string[] m = RandomMap(rng, rows, cols, round % 4 == 0 ? 0 : round % 4 == 1 ? 10 : round % 4 == 2 ? 25 : 40);
                string e = Check(rc, m, Reference(m));
                if (e != null) return e;
            }
            return null;
        });

        Run("large-maps", () =>
        {
            var rc = new RouteCounter();
            var corridor = new string[2000];
            corridor[0] = new string('.', 2000);
            for (int r = 1; r < 2000; r++) corridor[r] = new string('#', 1999) + ".";
            return Check(rc, Open(2000, 2000), Cap, "빈 맵 2000×2000")
                ?? Check(rc, corridor, 1, "2000×2000, 맨 윗줄과 맨 오른쪽 열만 통로")
                ?? Check(rc, Open(1, 2000), 1, "빈 맵 1×2000") ?? Check(rc, Open(2000, 1), 1, "빈 맵 2000×1")
                ?? Check(rc, Open(2000, 2000), Cap, "빈 맵 2000×2000(두 번째 호출)");
        }, null, "시간 초과(1초): 2000×2000 맵(400만 칸)이 끝나지 않습니다. 칸마다 상수 시간이면 수십 밀리초 안에 끝나야 합니다");
    }
}

