problems.solutionCode:
using System;
using System.Collections.Generic;

public static class LoadoutPlanner
{
    // costs[i] = i 번 아이템의 가격(1 이상). 서로 다른 아이템 slots 개를 골라 가격 합이 budget 이하인 조합을 모두 반환한다.
    // 각 조합은 아이템 번호를 오름차순으로 담은 배열이고, 목록은 사전순(첫 번호부터 비교)이다.
    public static List<int[]> AllLoadouts(int[] costs, int budget, int slots)
    {
        var result = new List<int[]>();
        var picked = new List<int>(slots);
        Fill(costs, budget, slots, 0, 0, picked, result);
        return result;
    }

    // start : 이번 슬롯에 넣을 수 있는 가장 작은 아이템 번호
    // spent : 지금까지 고른 아이템의 가격 합
    // picked: 지금까지 고른 아이템 번호(고른 순서 = 오름차순)
    private static void Fill(int[] costs, int budget, int slots, int start, int spent, List<int> picked, List<int[]> result)
    {
        // 기저 조건: 슬롯을 다 채웠으면 지금 상태를 "복사해서" 저장한다.
        // picked 는 계속 바뀌는 작업용 리스트라 그대로 넣으면 모든 결과가 같은 객체를 가리킨다.
        if (picked.Count == slots)
        {
            result.Add(picked.ToArray());
            return;
        }

        for (int i = start; i < costs.Length; i++)
        {
            // 가지치기: 가격은 모두 1 이상이라 합은 줄어들지 않는다. 지금 이미 넘으면 이 아이템 아래는 볼 필요가 없다.
            if (spent + costs[i] > budget) continue;

            picked.Add(i);                                                       // 선택
            Fill(costs, budget, slots, i + 1, spent + costs[i], picked, result); // 다음 슬롯: i 보다 큰 번호만
            picked.RemoveAt(picked.Count - 1);                                   // 선택 취소(되돌리기)
        }
    }
}
